def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Build a dictionary of class attributes
    cls_attrs = {}
    # Optional: use slots to restrict attributes
    cls_attrs['__slots__'] = tuple(fields) + ('srid',)

    # Define an __init__ that accepts positional or keyword arguments for the fields
    def __init__(self, *args, **kwargs):
        # accept positional arguments first
        if len(args) > len(fields):
            raise TypeError(f"__init__ expected at most {len(fields)} positional arguments, got {len(args)}")
        for f, v in zip(fields, args):
            setattr(self, f, v)
        # then fill missing fields from kwargs
        for f in fields:
            if f not in kwargs:
                continue
            setattr(self, f, kwargs[f])
