        srid_val = kwargs.get('srid')
        if srid_val is not None:
            if srid_val in srid_map:
                self.srid = srid_val
            else:
                raise ValueError(f"Unknown SRID: {srid_val}")
        else:
            self.srid = None

    cls_attrs['__init__'] = __init__

    # Optional: provide a helpful __repr__
    def __repr__(self):
        repr_vals = ', '.join(f'{f}={getattr(self, f)!r}' for f in fields)
        return f'{name}({repr_vals})'
    cls_attrs['__repr__'] = __repr__

    # Create and return the new type, subclassing a generic Point base if available,
    # otherwise fallback to object
    base = Point if 'Point' in globals() else object

    return type(name, (base,), cls_attrs)

