def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os
    import sys
    import shlex

    if not cmd:
        return cmd

    # Normalise only when on Windows
    if os.name != "nt":
        return cmd

    script = cmd[0]
    # Only handle typical script extensions
    if not script.lower().endswith((".py", ".pyw", ".txt", ".wscript", ".wsf", ".sct", ".ps1", ".psm1", ".psd1", ".ps1xml")):
        return cmd

    try:
        with open(script, "r", encoding="utf-8", errors="replace") as f:
            first_line = f.readline().strip()
    except Exception:
        return cmd

    if not first_line.startswith("#!"):
        return cmd

    try:
        # shlex handles quoted paths
        interpreter = shlex.split(first_line[2:].strip())[0]
    except Exception:
        return cmd

    # Handle python interpreters
    if interpreter.lower().startswith("python"):
        if not os.path.isabs(interpreter):
            interpreter = sys.executable
        else:
            # Append .exe if missing
            if os.path.splitext(interpreter)[1] == "":
                interpreter = interpreter + ".exe"

        new_cmd = tuple([interpreter, script] + list(cmd[1:]))
        return new_cmd

    # For non‑python interpreters, leave unchanged
    return cmd

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            if k in cache:
                return cache[k]
            if lock:
                with lock:
                    if k in cache:
                        return cache[k]
                    result = func(*args, **kwargs)
                    cache[k] = result
                    return result
            result = func(*args, **kwargs)
            cache[k] = result
            return result
        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        use_counts = {}
        def wrapper(*args, **kwargs):
            if typed:
                key = (args,
                       tuple(sorted(kwargs.items())),
                       tuple(type(arg) for arg in args),
                       tuple(type(v) for v in kwargs.values()))
            else:
                key = (args,
                       tuple(sorted(kwargs.items())))
            if key in cache:
                use_counts[key] += 1
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            use_counts[key] = 1
            if len(cache) > maxsize:
                min_count = min(use_counts.values())
                for k in use_counts:
                    if use_counts[k] == min_count:
                        evict_key = k
                        break
                del cache[evict_key]
                del use_counts[evict_key]
            return result
        return wrapper
    return decorator

