    callable that saves results in a cache.
    """
    def decorator(func):
        def wrapper(self, *args, **kwargs):
            # Compute the cache key using the provided key function
            cache_key = key(self, *args, **kwargs)

            # Try to return a cached value
            if lock is not None:
                lock.acquire()
                try:
                    if cache_key in cache:
                        return cache[cache_key]
                finally:
                    lock.release()
            else:
                if cache_key in cache:
                    return cache[cache_key]

            # Compute the result and cache it
            result = func(self, *args, **kwargs)

            if lock is not None:
                lock.acquire()
                try:
                    cache[cache_key] = result
                finally:
                    lock.release()
            else:
                cache[cache_key] = result

            return result

        return wrapper
    return decorator

def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    import traceback, os

    def _short_path(path):
        parts = path.split(os.sep)
        return os.sep.join(parts[-max_path_level:]) if len(parts) > max_path_level else path

    lines = []
    exc_type = type(e).__name__
    try:
        exc_msg = str(e)
    except Exception:
        exc_msg = "<unable to convert exception to string>"
    lines.append(f"{exc_type}: {exc_msg}")

    tb = e.__traceback__
    if tb:
        stack = traceback.extract_tb(tb)
        if len(stack) > max_level:
            stack = stack[-max_level:]
        for i, frame in enumerate(reversed(stack), 1):
            file_path = _short_path(frame.filename)
            lines.append(f"  {i} {file_path}:{frame.lineno} in {frame.name}")
            if frame.line:
                lines.append(f"    {frame.line.strip()}")

    for attr in ("__cause__", "__context__"):
        inner = getattr(e, attr, None)
        if inner and not (attr == "__context__" and getattr(e, "__suppress_context__", False)):
            if attr == "__cause__":
                lines.append("Caused by:")
            else:
                lines.append("During handling of the above exception, another exception occurred:")
            lines.extend(cls.extostr(inner, max_level, max_path_level).splitlines())

    return "\n".join(lines)

@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """Format an exception."""

    import os
    import traceback

    def _shorten_path(path):
        parts = path.split(os.sep)
        if len(parts) > max_path_level:
            return os.sep.join(parts[-max_path_level:])
        return path

    out_lines = []

    def _format_exception(exc, depth=0):
        if depth >= max_level:
            out_lines.append('... (maximum depth reached)')
            return

        tb = exc.__traceback__
        stack = traceback.extract_tb(tb)
        if stack:
            for file, line, func, code in stack:
                file_short = _shorten_path(file)
                out_lines.append(f'  at {file_short}:{line} in {func}')
                if code:
                    out_lines.append(f'    {code.strip()}')
        out_lines.append(f'{type(exc).__name__}: {exc}')

        # Handle chained exceptions
        if exc.__cause__:
            out_lines.append('Caused by:')
            _format_exception(exc.__cause__, depth + 1)
        elif exc.__context__ and not exc.__suppress_context__:
            out_lines.append('During handling of the above exception, another exception occurred:')
            _format_exception(exc.__context__, depth + 1)

    _format_exception(e)
    return '\n'.join(out_lines)

