    # Preserve original order while removing duplicates
    unique = []
    seen = set()
    for cls in classes:
        if cls not in seen:
            seen.add(cls)
            unique.append(cls)

    # Keep only those classes that are not ancestors of any other class in the list
    minimal = [
        cls
        for cls in unique
        if not any(other is not cls and issubclass(other, cls) for other in unique)
