        # Include class (and base class) attributes that are not methods or private
        for cls in self.__class__.mro():
            for key, val in getattr(cls, "__dict__", {}).items():
                if key.startswith("_") or callable(val):
                    continue
                attrs.add(key)
        # Include instance attributes
        attrs.update({k for k in getattr(self, "__dict__", {}) if not k.startswith("_")})
        return sorted(attrs)
    else:
        # Return only the instance's own public attributes
        return [k for k in getattr(self, "__dict__", {}) if not k.startswith("_")]

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if all:
        # Return every public attribute name, including methods and class attributes
        return [name for name in dir(self) if not name.startswith('_')]
    else:
        # Return only instance attributes that are not private and not callables
        return [name for name, value in vars(self).items()
                if not callable(value) and not name.startswith('_')]

def names(self, all=False): # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if hasattr(self, "_ATTRIBS"):
        return list(self._ATTRIBS.keys())
    return []

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Names declared on the instance
    attr_names = list(self.__dict__.keys())

    # Include annotated attributes declared on the class (PEP 526)
    annotations = getattr(self.__class__, "__annotations__", {})
    if annotations:
        for key in annotations:
            if key not in attr_names:
                attr_names.append(key)

    if all:
        # Include properties and other descriptors defined on the class
        for name, obj in vars(self.__class__).items():
            if isinstance(obj, property) and name not in attr_names:
                attr_names.append(name)
    return attr_names

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for item in sequence:
        if item is None:
            continue
        # If the item is a collection (but not a string/bytes), recurse into it
        if isinstance(item, (list, tuple, set)) and not isinstance(item, (str, bytes)):
            _normalizeargs(item, output)
        else:
            output.append(item)
    return output

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    for arg in sequence:
        # If the argument is a tuple or list, expand recursively
        if isinstance(arg, (tuple, list)):
            _normalizeargs(arg, output)
        else:
            # Assume arg is either a single interface or an implements spec
            output.append(arg)

    return output

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for item in sequence:
        if isinstance(item, tuple):
            # Recursively flatten nested tuples
            output.extend(_normalizeargs(item))
        else:
            # Append individual interfaces or implements specs unchanged
            output.append(item)
    return output

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if sequence is None:
        return output

    # If the sequence is iterable (list/tuple) expand recursively.
    # A single non-iterable argument is added as is.
    if isinstance(sequence, (list, tuple)):
        for item in sequence:
            _normalizeargs(item, output)
    else:
        output.append(sequence)

    return output

