        # expected to be a dictionary mapping coordinate names to a list of
        # integer indices.  If it is unavailable or the requested coordinate
        # does not exist we return an empty list.
        if not hasattr(self, "_err_indices"):
            return []
        return self._err_indices.get(coord_name, [])

