    return getattr(self, "_errors", {}).get(coord_name, [])

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Lazily build a mapping from coordinate names to the indices of
    # errors that refer to that coordinate.  This avoids scanning
    # the whole error list on every call and gives quick look‑ups.
    # If the mapping has already been built, simply return the cached
    # result.
    if not hasattr(self, "_err_indices_by_coord"):
        mapping = {}
        # ``self.errors`` is expected to be an iterable of error objects.
        # Each error is assumed to expose either a ``coords`` iterable
        # (e.g. a list of coordinate names) or a single ``coord`` string.
        for idx, err in enumerate(getattr(self, "errors", [])):
            coords = None
            if hasattr(err, "coords"):
                coords = err.coords
            elif hasattr(err, "coord"):
                coords = err.coord
            if isinstance(coords, (list, tuple, set)):
                for c in coords:
                    mapping.setdefault(c, []).append(idx)
            elif isinstance(coords, str):
                mapping.setdefault(coords, []).append(idx)
        self._err_indices_by_coord = mapping
    return self._err_indices_by_coord.get(coord_name, [])

def _update_context(self, context):
        """Update *context* with the properties of this graph.

        *context.error* is appended with indices of errors.
        Example subcontext for a graph with fields "E,t,error_E_low":
        {"error": {"x_low": {"index": 2}}}.
        Note that error names are called "x", "y" and "z"
        (this corresponds to first three coordinates,
        if they are present), which allows to simplify plotting.
        Existing values are not removed
        from *context.value* and its subcontexts.

        Called on "destruction" of the graph (for example,
        in :class:`.ToCSV`). By destruction we mean conversion
        to another structure (like text) in the flow.
        The graph object is not really destroyed in this process.
        """
        # Ensure the error dictionary exists on the context
        if not hasattr(context, "error") or context.error is None:
            context.error = {}
        # Attempt to work with a list of error definitions.
        # The expected format is a sequence of dictionaries with at least
        # the keys 'field' (the name of the error field) and 'index'
        # (an integer index).  If we don't see such an attribute, skip.
        if not hasattr(self, "errors"):
            return
        errors = getattr(self, "errors")
        if not isinstance(errors, (list, tuple)):
            return
        # Prepare a mapping from coordinate column names to the
        # output axis characters 'x', 'y', 'z'.
        # We assume that the first three non-error columns are the
        # coordinates that correspond to 'x', 'y', and 'z'.
        # Example: fields = ["E","t","error_E_low"] -> coordinate mapping {"E":"x","t":"y"}
        coord_map = {}
        # Determine the non-error columns
        if hasattr(self, "fields"):
            # Typical case where a `fields` attribute lists all columns
            all_cols = list(self.fields)
        else:
            # Fallback: try to retrieve column names from the data itself
            try:
                all_cols = list(self[0].keys()) if len(self) > 0 else []
            except Exception:
                all_cols = []
        for idx, col in enumerate(all_cols):
            if col.lower().startswith("error_"):
                continue
            if idx < 3:
                coord_map[col] = "xyz"[idx]
            else:
                # No more coordinate mapping needed beyond the first three
                break
        # Helper to translate a field name to an error key
        def _error_key(field_name):
            # Expected format: "error_<coord>_<suffix>"
            parts = field_name.split("_", 2)
            if len(parts) < 3 or parts[0] != "error":
                return None
            coord, suffix = parts[1], parts[2]
            axis = coord_map.get(coord, "x")  # default to 'x' if not found
            return f"{axis}_{suffix}"
        # Append each error index under the appropriate key
        for err in errors:
            if not isinstance(err, dict):
                continue
            field_name = err.get("field")
            index = err.get("index")
            if field_name is None or index is None:
                continue
            k = _error_key(field_name)
            if k is None:
                continue
            if k not in context.error:
                context.error[k] = {}
            # The value stored captures the index where the error appears
            context.error[k].update({"index": index})

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Treat Source instances separately to avoid treating them as a suitable sequence
    if isinstance(seq, Source):
        return False
    # Direct FillRequest instance satisfies the requirement
    if isinstance(seq, FillRequest):
        return True
    # Sequence-like objects (but not strings/bytes) are inspected for a FillRequest
    if isinstance(seq, (str, bytes)):
        return False
    try:
        for item in seq:
            if isinstance(item, FillRequest):
                return True
        return False
    except TypeError:
        # seq is not iterable
        return False

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # If seq itself is a FillRequest element, accept it
    if isinstance(seq, FillRequest):
        return True

    # Do not accept pure Source sequences
    if isinstance(seq, Source):
        return False

    # If seq is iterable (but not a string/bytes), check for at least one FillRequest
    try:
        iterator = iter(seq)
    except TypeError:
        # seq is not iterable, cannot be a sequence of FillRequests
        return False

    # Handle strings and bytes specially (they are iterable but not desired)
    if isinstance(seq, (str, bytes)):
        return False

    for item in iterator:
        if isinstance(item, FillRequest):
            return True

    return False

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # A helper to recursively search for a FillRequest instance
    def contains_fill_request(item):
        if isinstance(item, FillRequest):
            return True
        # inspect iterables (but not strings/bytes)
        if isinstance(item, (list, tuple, set)):
            return any(contains_fill_request(sub) for sub in item)
        # try generic iteration
        try:
            if not isinstance(item, (str, bytes)):
                for sub in item:
                    if contains_fill_request(sub):
                        return True
        except TypeError:
            # not iterable
            pass
        return False

    # The sequence must not be a Source element or container
    if isinstance(seq, Source):
        return False

    return contains_fill_request(seq)

