    return False

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # If the sequence itself is a FillRequest element, it's trivially a match
    if isinstance(seq, FillRequest):
        return True

    # Try to iterate over the elements of the sequence
    # Most sequence objects expose an `elements` attribute or are iterable
    elements = None
    if hasattr(seq, "elements"):
        elements = seq.elements
    elif hasattr(seq, "__iter__"):
        elements = seq

    # Check that we have a collection of elements
    if elements is None:
        return False

    # Search for at least one FillRequest in the sequence
    for el in elements:
        if isinstance(el, FillRequest):
            # Ensure the entire sequence is not a Source sequence
            return not isinstance(seq, Source)

    return False

