    def _next_level(l):
        return l - 1 if l > 0 else -1

    for key, val in d1.items():
        if key not in d2:
            # Key only in d1 -> include it
            result[key] = copy.deepcopy(val)
            continue

        other = d2[key]

        # If both values are dictionaries, we may need to recurse
        if isinstance(val, dict) and isinstance(other, dict):
            if level == 0:
                # Do not recurse: consider as values
                if val != other:
                    result[key] = copy.deepcopy(val)
            else:
                # Recurse with decremented level (or keep -1 for infinite)
                subdiff = difference(val, other, _next_level(level))
                if subdiff:
                    result[key] = subdiff
        else:
            # Non-dict values or mismatched types: include if different
            if val != other:
                result[key] = copy.deepcopy(val)

    return result

