    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # If we hit the recursion depth limit, return empty dict
    if level == 0:
        return {}

    result = {}
    # Iterate over each key in d1
    for key, v1 in d1.items():
        if key not in d2:
            # Key missing in d2: include the original value
            result[key] = v1
            continue

        v2 = d2[key]

        # If both values are dicts, compare recursively
        if isinstance(v1, dict) and isinstance(v2, dict):
            # Decide whether to descend further
            if level > 1 or level == -1:
                sub = difference(v1, v2, level - 1 if level > 0 else -1)
                if sub:
                    result[key] = sub
            elif level == 1:
                # At level 1, just check equality
                if v1 != v2:
                    result[key] = v1
            # If level < 1 we do not descend and skip
            continue

        # For non-dict values: if they differ, include from d1
        if v1 != v2:
            result[key] = v1

    return result

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    try:
        if not (self.min <= coord <= self.max):
            return
        bin_width = (self.max - self.min) / self.nbins
        index = int((coord - self.min) / bin_width)
        if index == self.nbins:
            index -= 1
        self.bins[index] += weight
        self.total += weight
    except AttributeError as exc:
        raise AttributeError(
            "Histogram object is missing one or more required attributes: "
            "min, max, nbins, bins, or total."
        ) from exc

