    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, (list, tuple)):
            result[key] = value  # keep list/tuple as-is; its contents are handled elsewhere
        else:
            result[key] = None
    if first_level:
        # Common identifying fields for a Kubernetes resource
        for identifier in ("apiVersion", "kind", "metadata"):
            if identifier in manifest_dict:
                result[identifier] = manifest_dict[identifier]
    return result

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value in
    ``last_applied_manifest`` if they are not yet present.
    """
    # Iterate over defined fields in the observer schema
    for field, subschema in observer_schema.items():
        # Skip if the response does not provide this field
        if field not in response:
            continue
        # Skip if the value already exists in the manifest
        if field in last_applied_manifest:
            continue
        value = response[field]
        # Handle nested dictionaries
        if isinstance(subschema, dict) and isinstance(value, dict):
            last_applied_manifest[field] = {}
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[field], subschema, value
            )
        # Handle lists where the subschema describes items
        elif isinstance(subschema, list) and len(subschema) == 1:
            last_applied_manifest[field] = []
            item_schema = subschema[0]
            for item in value:
                if isinstance(item_schema, dict) and isinstance(item, dict):
                    elem = {}
                    update_last_applied_manifest_list_from_resp(elem, item_schema, item)
                    last_applied_manifest[field].append(elem)
                else:
                    last_applied_manifest[field].append(item)
        else:
            # Primitive field: just copy the value
            last_applied_manifest[field] = value
    return last_applied_manifest

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value in
    ``last_applied_manifest`` if they are not yet present.
    """
    # Ensure the list has enough elements to index safely.
    # If the manifest is shorter, extend it proactively.
    for idx, schema_item in enumerate(observer_schema):
        # Extend the manifest list if it is too short.
        if idx >= len(last_applied_manifest):
            if idx < len(response):
                # Copy the corresponding response item into the manifest.
                # Use a shallow copy to avoid accidental reference sharing.
                last_applied_manifest.append(dict(response[idx]) if isinstance(response[idx], dict) else response[idx])
            else:
                # No data in the response – nothing to initialise.
                continue

        # Skip if nothing to observe for this item.
        if not schema_item or idx >= len(response):
            continue

        # If the schema item is a dictionary, we assume it maps field names to
        # sub‑schemas describing nested structures. We recurse as necessary.
        if isinstance(schema_item, dict):
            src_item = response[idx]
            tgt_item = last_applied_manifest[idx]
            for key, sub_schema in schema_item.items():
                # If the key is missing in the target, initialise it with the
                # corresponding value from the response (if present).
                if key not in tgt_item:
                    if key not in src_item:
                        # No data available in the response for this key – skip.
                        continue
                    if isinstance(sub_schema, list):
                        # Nested list – initialise an empty list and recurse.
                        tgt_item[key] = []
                        update_last_applied_manifest_list_from_resp(
                            tgt_item[key], sub_schema, src_item[key]
                        )
                    elif isinstance(sub_schema, dict):
                        # Nested dict – initialise an empty dict and recurse.
                        tgt_item[key] = {}
                        update_last_applied_manifest_dict_from_resp(
                            tgt_item[key], sub_schema, src_item[key]
                        )
                    else:
                        # Primitive value – copy directly.
                        tgt_item[key] = src_item[key]
                else:
                    # If the key is already present, we still need to ensure
                    # that nested structures are fully populated. Recurse if
                    # appropriate.
                    if isinstance(sub_schema, list):
                        update_last_applied_manifest_list_from_resp(
                            tgt_item[key], sub_schema, src_item.get(key, [])
                        )
                    elif isinstance(sub_schema, dict):
                        update_last_applied_manifest_dict_from_resp(
                            tgt_item[key], sub_schema, src_item.get(key, {})
                        )
        else:
            # If the schema item is not a dictionary, we treat it as a leaf
            # attribute and simply copy the value if it exists.
            if idx < len(response) and isinstance(schema_item, (str, int)):
                key = schema_item
                if key not in last_applied_manifest[idx]:
                    if key in response[idx]:
                        last_applied_manifest[idx][key] = response[idx][key]
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for key, sub_schema in observer_schema.items():
        # Ensure the field exists in the response
        if key not in response:
            raise KeyError(f"Field '{key}' not found in the Kubernetes response")

        # If the key is not yet in last_applied_manifest, set it
        if key not in last_applied_manifest:
            last_applied_manifest[key] = (
                {} if isinstance(sub_schema, dict) and isinstance(response[key], dict) else response[key]
            )

        # If the observed schema is nested, recurse into it
        if isinstance(sub_schema, dict) and isinstance(response[key], dict):
            # Create a nested dict if it wasn't already set
            if not isinstance(last_applied_manifest[key], dict):
                last_applied_manifest[key] = {}
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], sub_schema, response[key]
            )

