def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Determine the specification version to use
    spec_version = getattr(self, "spec_version", None)
    if extract_spec_version:
        typ = inventory.get("type")
        if typ is not None:
            try:
                # Try to interpret the type as a numeric version
                if isinstance(typ, str):
                    typ_val = float(typ.rstrip("vV"))  # allow leading 'v'
                else:
                    typ_val = float(typ)
                spec_version = typ_val
            except Exception:
                # Fall back to the original spec_version if conversion fails
                pass

    # Basic inventory checks
    if not isinstance(inventory, dict):
        raise TypeError("Inventory must be a dictionary")

    # Example required top-level key checks
    required_top_keys = ["metadata", "elements"]
    for key in required_top_keys:
        if key not in inventory:
            raise ValueError(f"Inventory missing required key: '{key}'")

    # If metadata exists, check mandatory fields
    metadata = inventory["metadata"]
    if not isinstance(metadata, dict):
        raise TypeError("metadata must be a dictionary")
    if "name" not in metadata:
        raise ValueError("metadata missing required 'name' field")
    if "version" in metadata:
        try:
            float(metadata["version"])
        except Exception:
            raise ValueError("metadata 'version' must be a numeric value")

    # Validate each element in the list
    elements = inventory["elements"]
    if not isinstance(elements, list):
        raise TypeError("elements must be a list")
    for idx, elem in enumerate(elements):
        if not isinstance(elem, dict):
            raise TypeError(f"Element at index {idx} must be a dict")
        for req in ("id", "type"):
            if req not in elem:
                raise ValueError(f"Element at index {idx} missing required field '{req}'")

    # Optional: spec_version based checks
    if isinstance(spec_version, (int, float)):
        # For spec_version >= 2.0, require an 'author' field in metadata
        if spec_version >= 2.0 and "author" not in metadata:
            raise ValueError("metadata must contain 'author' for spec_version >= 2.0")

    # If all checks pass, return True
    return True

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # ------------------------------------------------------------------
    # 1. Try to extract a spec version from the ``type`` field if asked
    # ------------------------------------------------------------------
    if extract_spec_version:
        type_field = inventory.get('type') if isinstance(inventory, dict) else None
        if isinstance(type_field, str):
            # Common patterns: ``inventory.v1`` or ``spec:1.0`` or similar.
            # We will interpret the part after the last separator as the version.
            for sep in ('.', ':'):
                if sep in type_field:
                    _, version = type_field.rsplit(sep, 1)
                    if version and version.replace('.', '').isdigit():
                        self.spec_version = version
                        break
        # If we failed to find a usable version, fall back to the existing
        # ``self.spec_version`` (if any) – any later checks will raise if it
        # remains unset.

    # ------------------------------------------------------------------
    # 2. Ensure a spec version is available
    # ------------------------------------------------------------------
    if not getattr(self, 'spec_version', None):
        raise ValueError('Specification version is not set and cannot be inferred from the inventory')

    # ------------------------------------------------------------------
    # 3. Perform basic type checks on the inventory object
    # ------------------------------------------------------------------
    if not isinstance(inventory, dict):
        raise TypeError(f'Expected inventory to be a dict, got {type(inventory).__name__}')

    # ------------------------------------------------------------------
    # 4. Validate structure according to the specification version
    # ------------------------------------------------------------------
    errors = []

    def _missing(key):
        errors.append(f'Missing required key: {key}')

    def _type_error(key, expected_type):
        errors.append(f'Key "{key}" should be of type {expected_type.__name__}')

    # Example schemas – these should be adapted to the real specifications.
    spec_schemas = {
        '1.0': {
            'required': ['id', 'name', 'entries'],
            'types': {
                'id': str,
                'name': str,
                'entries': list,
            },
        },
        '2.0': {
            'required': ['uuid', 'metadata', 'components'],
            'types': {
                'uuid': str,
                'metadata': dict,
                'components': dict,
            },
        },
    }

    schema = spec_schemas.get(self.spec_version)
    if not schema:
        raise ValueError(f'Unsupported specification version: {self.spec_version}')

    for key in schema['required']:
        if key not in inventory:
            _missing(key)

    for key, expected in schema['types'].items():
        if key in inventory and not isinstance(inventory[key], expected):
            _type_error(key, expected)

    # ------------------------------------------------------------------
    # 5. Report any collected validation errors
    # ------------------------------------------------------------------
    if errors:
        raise ValueError('Inventory validation failed: ' + '; '.join(errors))

    # If we reach here, the inventory is considered valid
    return True

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Determine specification version
    spec_version = self.spec_version
    if extract_spec_version and hasattr(inventory, 'type'):
        t = inventory.type
        if isinstance(t, str) and t.strip():
            try:
                spec_version = float(t)
            except ValueError:
                pass

    # Basic validation checks
    errors = []

    if not hasattr(inventory, 'id'):
        errors.append('inventory missing id')
    if not hasattr(inventory, 'items'):
        errors.append('inventory missing items')
    else:
        seen = set()
        for item in inventory.items:
            if hasattr(item, 'id'):
                if item.id in seen:
                    errors.append(f'duplicate id {item.id}')
                seen.add(item.id)

    if errors:
        raise ValueError('Validation errors: ' + '; '.join(errors))

    return spec_version

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Extract all digests that are actually present in the manifest
    digests_in_manifest = set()
    for entry in manifest_files:
        if isinstance(entry, dict):
            digest = entry.get("digest")
        else:
            digest = getattr(entry, "digest", None)
        if digest:
            digests_in_manifest.add(digest)

    # Digests that should be there but are missing
    missing = digests_used - digests_in_manifest
    # Digests that are present in the manifest but not used
    unused = digests_in_manifest - digests_used

    if missing or unused:
        parts = []
        if missing:
            parts.append(f"Missing digests: {', '.join(sorted(missing))}")
        if unused:
            parts.append(f"Unused digests: {', '.join(sorted(unused))}")
        raise ValueError("Digest check failed: " + "; ".join(parts))

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if prior is None:
        raise ValueError("prior argument is None")
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator")
    # Ensure that the prior version is strictly older
    if hasattr(self, "version") and hasattr(prior, "version"):
        if prior.version >= self.version:
            raise ValueError(
                f"Prior inventory version {prior.version!r} must be "
                f"less than current version {self.version!r}"
            )
    # Verify that all IDs present in the prior inventory are still present
    if hasattr(self, "ids") and hasattr(prior, "ids"):
        missing_ids = set(prior.ids) - set(self.ids)
        if missing_ids:
            raise ValueError(f"Current inventory missing IDs from prior: {missing_ids}")
    # Additional domain‑specific consistency checks could be added here
    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type safety
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an instance of InventoryValidator")

    # Assume that each InventoryValidator exposes a timestamp (or date) field
    # and a mapping of items known as `items`. If the names differ, fall back
    # to generic attribute access using `getattr`.
    try:
        self_ts = self.timestamp
        prior_ts = prior.timestamp
    except AttributeError:
        try:
            self_ts = getattr(self, "date", None)
            prior_ts = getattr(prior, "date", None)
            if self_ts is None or prior_ts is None:
                raise AttributeError
        except AttributeError:
            raise AttributeError(
                "Both inventories must expose a 'timestamp' or 'date' attribute"
            )

    # Verify chronological order
    if self_ts <= prior_ts:
        raise ValueError(
            f"Current inventory timestamp ({self_ts}) is not newer than prior ({prior_ts})"
        )

    # Now ensure every entry in the prior inventory exists in the current one
    # and is newer or at least as recent. The exact representation of items
    # may vary; we assume items are mapping keys pointing to comparable values.
    try:
        self_items = self.items
        prior_items = prior.items
    except AttributeError:
        try:
            self_items = getattr(self, "data", {})
            prior_items = getattr(prior, "data", {})
            if not isinstance(self_items, dict) or not isinstance(prior_items, dict):
                raise AttributeError
        except AttributeError:
            raise AttributeError(
                "Both inventories must expose an 'items' or 'data' dictionary of entries"
            )

    for key, prior_value in prior_items.items():
        if key not in self_items:
            raise ValueError(f"Item '{key}' present in prior inventory is missing in current inventory")
        current_value = self_items[key]
        # If the values themselves are timestamps or versions, compare them
        # Otherwise, perform a generic comparison that falls back to equality
        try:
            if current_value <= prior_value:
                raise ValueError(
                    f"Item '{key}' in current inventory is not newer than in prior inventory"
                )
        except TypeError:
            # If values are not directly comparable, fallback to string comparison
            if str(current_value) <= str(prior_value):
                raise ValueError(
                    f"Item '{key}' in current inventory is not newer (string comparison) than in prior inventory"
                )

    # All checks passed
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Initialize the mapping
    path_map = {}

    # Get all versions to consider: the given version and any later versions
    # (assuming version comparison is valid; adjust as needed for your version type)
    versions_to_consider = [v for v in inventory.keys() if v >= version]
    versions_to_consider.sort()

    for v in versions_to_consider:
        state = inventory.get(v, {})
        if not isinstance(state, dict):
            # If for some reason the state entry is not a dict, skip it
            continue
        for logic_path, files in state.items():
            # Ensure we treat files as a set
            if isinstance(files, (list, set, tuple)):
                file_set = set(files)
            else:
                file_set = {files}
            if logic_path in path_map:
                path_map[logic_path].update(file_set)
            else:
                path_map[logic_path] = file_set

    return path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Build mapping for the given version and all later versions
    mapping = {}
    # Determine order of versions – if they are comparable, sort them
    try:
        sorted_versions = sorted(inventory.keys())
    except TypeError:
        # If the keys are not comparable, fall back to the provided order
        sorted_versions = list(inventory.keys())
    # Find the index of the target version (if present)
    start_index = 0
    for i, v in enumerate(sorted_versions):
        if v == version:
            start_index = i
            break
    # Iterate over the target version and all later versions
    for v in sorted_versions[start_index:]:
        # Each entry in inventory[v] is expected to be a mapping or a tuple
        entries = inventory.get(v, [])
        for entry in entries:
            if isinstance(entry, dict):
                logical_path = entry.get("logical_path") or entry.get("logicalPath")
                content_file = entry.get("content_file") or entry.get("contentFile")
            else:  # assume tuple or sequence
                # Try to extract logical path and content file by position
                try:
                    logical_path, content_file = entry[:2]
                except Exception:
                    continue
            if logical_path is None or content_file is None:
                continue
            mapping.setdefault(logical_path, set()).add(content_file)
    return mapping

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
