    """
    result = {}
    for logical_path, version_map in inventory.items():
        files = set()
        if isinstance(version_map, dict):
            # mapping from version -> file
            for v, f in version_map.items():
                try:
                    if v >= version:
                        files.add(f)
                except Exception:
                    # fallback string comparison
                    if v >= version:
                        files.add(f)
        elif isinstance(version_map, list):
            # list of tuples (version, file)
            for v, f in version_map:
                try:
                    if v >= version:
                        files.add(f)
                except Exception:
                    if v >= version:
                        files.add(f)
        else:
            # single file for the logical path
            if version_map == version:
                files.add(version_map)
        if files:
            result[logical_path] = files
    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_map = {}
    # First try to obtain the state for the requested version.
    # 1. If inventory behaves like a mapping indexed by version:
    state_obj = None
    if isinstance(inventory, dict):
        state_obj = inventory.get(version)
    # 2. If inventory has a get_state or get_view method:
    if state_obj is None:
        for name in ("get_state", "get_view", "get_version"):
            if hasattr(inventory, name):
                try:
                    state_obj = getattr(inventory, name)(version)
                except Exception:
                    state_obj = None
                if state_obj is not None:
                    break
    if state_obj is None:
        raise ValueError(f"Cannot retrieve state for version '{version}' from inventory")

    # 3. Iterate over the items in the state object.
    # The structure of items is not fixed, so we support a few common conventions.
    try:
        for entry in state_obj:
            # Look for a mapping-like entry with logical_path and content_files
            if isinstance(entry, dict):
                logical = entry.get("logical_path") or entry.get("state")  # fall back to state if logical_path missing
                if logical is None:
                    continue
                files = entry.get("content_files") or entry.get("files") or entry.get("file") or entry.get("text")
                if files is None:
                    continue
                if not isinstance(files, (list, set, tuple)):
                    files = {files}
                logical_map.setdefault(logical, set()).update(files)
                continue

            # If the entry is an object, try to read attributes
            logical = getattr(entry, "logical_path", None) or getattr(entry, "state", None)
            if logical is None:
                continue
            files = getattr(entry, "content_files", None) or getattr(entry, "files", None) \
                    or getattr(entry, "file", None) or getattr(entry, "text", None)
            if files is None:
                continue
            if not isinstance(files, (list, set, tuple)):
                files = {files}
            logical_map.setdefault(logical, set()).update(files)

    except Exception as exc:
        raise ValueError(f"Failed to iterate over state entries for version '{version}': {exc}") from exc

    return logical_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for a given version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may include references to duplicate files in later
    versions than the version being described.
    """
    # Resolve the structure that contains the state per version.
    # Accept a dict-like inventory or an object with a ``states`` attribute.
    if hasattr(inventory, "states"):
        state_dict = inventory.states
    elif isinstance(inventory, dict) and "states" in inventory:
        state_dict = inventory["states"]
    else:
        state_dict = inventory

    # Prepare the mapping result.
    result = {}

    # Helper to compare versions whether they match or are later.
    def version_greater_or_equal(v1, v2):
        try:
            # Numeric comparison if possible
            return float(v1) >= float(v2)
        except Exception:
            # Fallback: string comparison
            return str(v1) >= str(v2)

    # If a specific version is supplied, find all versions >= given one;
    # otherwise treat the input inventory as a single version mapping.
    if version is None:
        relevant_versions = [state_dict]
    else:
        relevant_versions = [
            state for ver, state in state_dict.items()
            if version_greater_or_equal(ver, version)
        ]

    # Iterate through all relevant versions and merge file sets.
    for state in relevant_versions:
        if not isinstance(state, dict):
            continue
        for logical_path, files in state.items():
            # Normalise files to an iterable
            if isinstance(files, (set, list, tuple)):
                file_set = set(files)
            elif isinstance(files, str):
                file_set = {files}
            else:
                # Unsupported type, skip
                continue
            result.setdefault(logical_path, set()).update(file_set)

    return result

def validate_fixity(self, fixity, manifest_files):
