        if "file" not in fixity:
            raise ValueError("Fixity block missing required 'file' section")
        files = fixity["file"]
        # allow a single file mapping as well as a list of files
        if isinstance(files, dict):
            files = [files]
        if not isinstance(files, list):
            raise ValueError("'file' section must be a list or dict")

        seen_ids = set()
        for i, f in enumerate(files):
            if not isinstance(f, dict):
                raise ValueError(f"File entry {i} is not a mapping")

