    child_lines = []
    try:
        for child in self:
            if callable(getattr(child, "pretty", None)):
                child_lines.append(child.pretty(indent + 1, debug))
    except TypeError:
        # self is not iterable – no children
        pass

    if child_lines:
        # Body with children
        closing_tag = f"{indent_str}</{self.__class__.__name__}>"
        return "\n".join([opening_tag] + child_lines + [closing_tag])
    else:
        # Self-closing tag if no children
        if debug:
            # In debug mode provide full representation of the object
            return f"{opening_tag.rstrip('>')} / >"
        else:
            return f"{opening_tag.rstrip('>')} />"

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    indent_str = '  ' * indent
    # Determine the element's tag name
    tag = getattr(self, 'tag', getattr(self, 'tagName', type(self).__name__))
    # Start constructing the opening tag
    parts = [f"{indent_str}<{tag}"]
    # Add any attributes defined on the object
    for attr_name in getattr(self, 'attributes', {}):
        value = getattr(self, attr_name, None)
        if value is not None:
            parts.append(f' {attr_name}="{value}"')
    parts.append('>')
    # Add children recursively if they exist
    children = []
    if hasattr(self, 'children'):
        children = list(self.children)
    else:
        # Fallback: iterate over all members that look like child elements
        for member in getattr(self, '__iter__', lambda: []())():
            if hasattr(member, 'pretty'):
                children.append(member)
    if children:
        parts.append('\n')
        for child in children:
            if hasattr(child, 'pretty'):
                parts.append(child.pretty(indent + 1, debug))
            else:
                parts.append(f"{'  ' * (indent + 1)}{repr(child)}\n")
        parts.append(f"{indent_str}</{tag}>\n")
    else:
        parts.append(f"</{tag}>\n")
    # Optionally include debug information
    if debug and hasattr(self, 'id'):
        parts.append(f"{indent_str}<!-- id={self.id} -->\n")
    return ''.join(parts)

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Convert to a mutable list
    exprs = list(args)

    # Helper predicates that work with e.g. sympy-like objects
    def is_and(x):
        return hasattr(x, "func") and getattr(x.func, "__name__", None) == "And"

    def is_or(x):
        return hasattr(x, "func") and getattr(x.func, "__name__", None) == "Or"

    def is_not(x):
        return hasattr(x, "func") and getattr(x.func, "__name__", None) == "Not"

    def args_of(x):
        return getattr(x, "args", (x,))

    # Simplify iteratively until no changes occur
    changed = True
    while changed:
        changed = False
        new_exprs = []

        for e in exprs:
            # Skip duplicates
            if any(e == n for n in new_exprs):
                changed = True
                continue

            # Try absorption with any other expression in the list
            simplified = False
            for n in exprs:
                if e == n:
                    continue

                # Absorption: A & (A | B) -> A
                if is_and(e) and is_or(n):
                    if any(e == a for a in n.args):
                        simplified = True
                        break

                # Absorption: A | (A & B) -> A
                if is_or(e) and is_and(n):
                    if any(e == a for a in n.args):
                        simplified = True
                        break

                # Negative absorption: A & (~A | B) -> A & B
                if is_and(e) and is_or(n) and len(n.args) == 2:
                    a, b = n.args
                    if is_not(a) and a.args[0] == e:
                        e = And(e, b)  # noqa: F821 – assumed available in the surrounding context
                        simplified = True
                        break

                # Negative absorption: A | (~A & B) -> A | B
                if is_or(e) and is_and(n) and len(n.args) == 2:
                    a, b = n.args
                    if is_not(a) and a.args[0] == e:
                        e = Or(e, b)  # noqa: F821 – assumed available in the surrounding context
                        simplified = True
                        break

            if simplified:
                changed = True

            new_exprs.append(e)

        if len(new_exprs) != len(exprs):
            changed = True
        exprs = new_exprs

    return exprs

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Helper predicates
    def is_var(expr):
        return isinstance(expr, str)

    def is_not(expr):
        return isinstance(expr, tuple) and expr[0] == '~'

    def simplify(expr):
        """
        Recursively simplify a single expression according to absorption rules.
        Expressions are represented as:
          - a variable: a string
          - a negation: ('~', operand)
          - a binary operation: ('&', left, right) or ('|', left, right)
        """
        if is_var(expr):
            return expr

        op = expr[0]
        operands = tuple(simplify(o) for o in expr[1:])

        # Binary operations only support two operands
        if op in ('&', '|') and len(operands) == 2:
            a, b = operands

            # Basic absorption: A op A => A
            if a == b:
                return a

            # Helper to match (op, a, something) patterns
            def match_op(inner_op, inner_a, inner_b):
                return isinstance(inner_a, tuple) and inner_a[0] == inner_op and inner_b == a

            # Absorption patterns
            if op == '&':
                # A & (A | B) => A
                if isinstance(b, tuple) and b[0] == '|':
                    if b[1] == a or b[2] == a:
                        return a
                # Negative absorption
                if isinstance(b, tuple) and b[0] == '|':
                    # A & (~A | B) => A & B
                    if is_not(b[1]) and b[1][1] == a:
                        return simplify(('&', a, b[2]))
                    if is_not(b[2]) and b[2][1] == a:
                        return simplify(('&', a, b[1]))
            elif op == '|':
                # A | (A & B) => A
                if isinstance(b, tuple) and b[0] == '&':
                    if b[1] == a or b[2] == a:
                        return a
                # Negative absorption
                if isinstance(b, tuple) and b[0] == '&':
                    # A | (~A & B) => A | B
                    if is_not(b[1]) and b[1][1] == a:
                        return simplify(('|', a, b[2]))
                    if is_not(b[2]) and b[2][1] == a:
                        return simplify(('|', a, b[1]))

        # No rule applied: return the possibly simplified expression
        return (op, *operands)

    # Simplify each expression in the list and return new list
    return [simplify(expr) for expr in args]

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def wrapper(localtime):
        name = namefunc(localtime)
        try:
            # In Python 2, unicode objects need to be encoded to bytes
            if isinstance(name, unicode):  # noqa: F821
                return name.encode('utf-8')
        except NameError:
            # In Python 3, `unicode` is not defined – no conversion needed
            pass
        return name
    return wrapper

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    name = namefunc()
    # No conversion needed for Python 3
    if sys.version_info[0] > 2:
        return name
    # In Python 2, ensure we return a byte string
    if name is None:
        return None
    if isinstance(name, unicode):
        # Prefer utf-8 encoding, fall back to latin-1 if necessary
        try:
            return name.encode('utf-8')
        except UnicodeEncodeError:
            return name.encode('latin-1')
    return name  # already a byte string (str in py2) or other type

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    def wrapper(*args, **kwargs):
        out = namefunc(*args, **kwargs)
        if sys.version_info[0] < 3 and isinstance(out, unicode):
            return out.encode('utf-8')
        return out
    return wrapper

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def wrapper(*args, **kwargs):
        import sys
        result = namefunc(*args, **kwargs)
        if sys.version_info[0] < 3:
            # Python 2: only encode unicode to byte string
            try:
                if isinstance(result, unicode):  # noqa: F821
                    return result.encode("utf-8")
            except NameError:
                # 'unicode' not defined in Python 3; skip
                pass
        else:
            # Python 3: encode str (unicode) to bytes
            if isinstance(result, str):
                return result.encode("utf-8")
        return result
    wrapper.__name__ = namefunc.__name__
    wrapper.__doc__ = namefunc.__doc__
    return wrapper

