                rendered.append(
                    piece[style]
                    if style in piece
                    else piece.get("default", "")
                )
            else:
                rendered.append(str(piece))
        return json.dumps(rendered)

    # For other styles, build a string representation
    result_parts = []

    for piece in pieces:
        if piece is None:
