def bash_completion():
    '''
    Return a bash completion script for the borgmatic command.
    Produce this by introspecting borgmatic's command-line argument parsers.
    '''
    import importlib
    try:
        cli_module = importlib.import_module('borgmatic.cli')
    except Exception as e:
        return f'# Could not import borgmatic.cli: {e}\n'
    main_cmd = getattr(cli_module, 'cli', None)
    if main_cmd is None:
        return '# borgmatic.cli.cli not found\n'
    # Try Click's built‑in Bash completion
    try:
        import click
        from click import shell_completion
        if hasattr(shell_completion, 'get_completion_script'):
            return shell_completion.get_completion_script(main_cmd, name='borgmatic', shell='bash')
    except Exception:
        pass
    # Fallback: Use argparse introspection if the CLI is an argparse parser
    try:
        import argparse
        if isinstance(main_cmd, argparse.ArgumentParser):
            opts = [
                action.option_strings[0]
                for action in main_cmd._actions
                if action.option_strings
            ]
            subcmds = []
            for action in main_cmd._actions:
                if isinstance(action, argparse._SubParsersAction):
                    subcmds = list(action.choices.keys())
                    break
            all_words = opts + subcmds
            script = (
                ' _borgmatic_complete() {\n'
                '    local cur words\n'
                '    _init_completion -n = || return\n'
                '    COMPREPLY=( $(compgen -W \'\n'
                f"            {' '.join(all_words)}\n"
                "            \' -- \"$cur\") )\n"
                ' }\n'
                ' complete -F _borgmatic_complete borgmatic\n'
            )
            return script
    except Exception:
        pass
    return '# Unable to generate bash completion script for borgmatic.\n'

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed = {}
    remaining_sets = []
    for name, parser in subparsers.items():
        namespace, remaining = parser.parse_known_args(unparsed_arguments)
        parsed[name] = namespace
        remaining_sets.append(set(remaining))
    if remaining_sets:
        common_remaining = set.intersection(*remaining_sets)
        remaining_args = [arg for arg in unparsed_arguments if arg in common_remaining]
    else:
        remaining_args = unparsed_arguments[:]
    return parsed, remaining_args

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

    Examples::

        >>> size_to_bytes("500")
        500
        >>> size_to_bytes("1K")
        1000
    """
    size = size.strip()
    import re
    m = re.match(r'^([\d\.]+)\s*([kmgtpezyw]?b?)?$', size, re.IGNORECASE)
    if not m:
        raise ValueError(f"invalid size value {size!r}")
    number = float(m.group(1))
    unit = (m.group(2) or "").upper()
    # Handle 'KB', 'K', etc.
    if unit in ("", "B"):
        multiplier = 1
    elif unit in ("K", "KB"):
        multiplier = 10**3
    elif unit in ("M", "MB"):
        multiplier = 10**6
    elif unit in ("G", "GB"):
        multiplier = 10**9
    elif unit in ("T", "TB"):
        multiplier = 10**12
    elif unit in ("P", "PB"):
        multiplier = 10**15
    elif unit in ("E", "EB"):
        multiplier = 10**18
    elif unit in ("Z", "ZB"):
        multiplier = 10**21
    elif unit in ("Y", "YB"):
        multiplier = 10**24
    else:
        raise ValueError(f"Unknown size unit {unit!r}")
    return int(round(number * multiplier))

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for k, v in d.items():
            result[k] = result.get(k, 0) + v
    return result

