def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url_args:
        return url
    # Try Python format syntax, e.g. "http://example.com/{id}"
    try:
        return url.format(**url_args)
    except KeyError as e:
        # Not a format placeholder – try %-style interpolation
        try:
            return url % url_args
        except Exception as exc:
            # If either interpolation fails, raise a helpful error
            missing = e.args[0] if isinstance(e, KeyError) else None
            msg = "Failed to replace URL placeholders"
            if missing:
                msg += f" (missing key: {missing})"
            raise ValueError(msg) from exc

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url_args:
        return url
    import re
    pattern = re.compile(r'\{(\w+)\}')
    def repl(m):
        key = m.group(1)
        return str(url_args.get(key, m.group(0)))
    return pattern.sub(repl, url)

