        raise ValueError("Alphabet must contain at least one character")

    base = len(alphabet)

    # Special case for zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        result = ''.join(reversed(digits))

    if padding is not None:
        pad_len = padding - len(result)
        if pad_len > 0:
            result = alphabet[0] * pad_len + result

    return result

def _replace_register(flow_params, register_number, register_value):
    """
    Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    """
    def _recurse(item):
        if isinstance(item, dict):
            for k, v in item.items():
                if isinstance(v, (dict, list, tuple)):
                    _recurse(v)
                else:
                    if v == register_value:
                        item[k] = register_number
        elif isinstance(item, (list, tuple)):
            for idx, elem in enumerate(item):
                if isinstance(elem, (dict, list, tuple)):
                    _recurse(elem)
                else:
                    if elem == register_value:
                        item[idx] = register_number

    _recurse(flow_params)
    return flow_params

def _replace_register(flow_params, register_number, register_value):
    """
    Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    """
    if not isinstance(flow_params, dict):
        return flow_params
    for key, value in list(flow_params.items()):
        if isinstance(value, dict):
            flow_params[key] = _replace_register(value, register_number, register_value)
        elif isinstance(value, list):
            new_list = []
            for item in value:
                if isinstance(item, (dict, list)):
                    new_list.append(_replace_register(item, register_number, register_value))
                else:
                    new_list.append(item)
            flow_params[key] = new_list
        elif value == register_value:
            flow_params[key] = register_number
    return flow_params

def _replace_register(flow_params, register_number, register_value):
