def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    all_subs = set()

    def _gather(sub_cls):
        for sub in sub_cls.__subclasses__():
            if sub not in all_subs:
                all_subs.add(sub)
                _gather(sub)

    _gather(cls)
    return list(all_subs)

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two symbols.")
    # Build a quick lookup for digit values
    digit_map = {ch: idx for idx, ch in enumerate(alphabet)}
    value = 0
    for ch in string:
        if ch not in digit_map:
            raise ValueError(f"Character {ch!r} not in alphabet.")
        value = value * base + digit_map[ch]
    return value

