def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base == 0:
        raise ValueError("Alphabet must contain at least one symbol.")
    # Create a mapping from alphabet characters to their integer values.
    value_map = {ch: idx for idx, ch in enumerate(alphabet)}
    value = 0
    for ch in string:
        if ch not in value_map:
            raise ValueError(f"Character {ch!r} not found in alphabet.")
        value = value * base + value_map[ch]
    return value

