def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Determine platform if auto
    import sys
    if platform == 'this':
        platform = 1 if not sys.platform.startswith('win') else 0

    # POSIX: fallback to shlex for simplicity and correctness
    if platform == 1:
        import shlex
        return shlex.split(s)

    # Windows: implement according to Microsoft's algorithm
    if platform == 0:
        tokens = []
        cur = ''
        inquote = False
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch == '\\':
                # Count consecutive backslashes
                j = i
                while j < n and s[j] == '\\':
                    j += 1
                backslashes = j - i
                if j < n and s[j] == '"':
                    # Escape sequence before a quote
                    cur += '\\' * (backslashes // 2)
                    if backslashes % 2 == 0:
                        # toggle quote
                        inquote = not inquote
                    else:
                        # literal quote
                        cur += '"'
                    i = j + 1
                else:
                    # Backslashes not followed by quote
                    cur += '\\' * backslashes
                    i = j
            elif ch == '"':
                inquote = not inquote
                i += 1
            elif ch.isspace() and not inquote:
                if cur:
                    tokens.append(cur)
                    cur = ''
                i += 1
                # Skip additional whitespace
                while i < n and s[i].isspace():
                    i += 1
            else:
                cur += ch
                i += 1
        if cur:
            tokens.append(cur)
        return tokens

    # Unsupported platform value
    raise ValueError(f"Unsupported platform value: {platform}")

