def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    if isinstance(frequency, str) and frequency.strip().lower() == "always":
        return None
    if not isinstance(frequency, str):
        raise ValueError("Frequency must be a string or None")

    parts = frequency.strip().split()
    if len(parts) != 2:
        raise ValueError(f"Unrecognized frequency format: {frequency!r}")
    num_str, unit = parts
    try:
        num = int(num_str)
    except ValueError:
        raise ValueError(f"Invalid number in frequency: {num_str!r}")
    unit = unit.lower()

    if unit in ('day', 'days'):
        return datetime.timedelta(days=num)
    elif unit in ('week', 'weeks'):
        return datetime.timedelta(weeks=num)
    elif unit in ('hour', 'hours'):
        return datetime.timedelta(hours=num)
    elif unit in ('minute', 'minutes', 'min', 'mins'):
        return datetime.timedelta(minutes=num)
    elif unit in ('second', 'seconds', 'sec', 'secs'):
        return datetime.timedelta(seconds=num)
    else:
        raise ValueError(f"Unknown time unit in frequency: {unit!r}")

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq = frequency.strip()
    if not freq:
        return None
    if freq.lower() == 'always':
        return None

    parts = freq.split()
    if len(parts) != 2:
        raise ValueError(f"Frequency '{frequency}' cannot be parsed.")
    num_str, unit = parts

    try:
        value = float(num_str) if '.' in num_str else int(num_str)
    except ValueError:
        raise ValueError(f"Frequency number '{num_str}' is not a valid number.")

    unit = unit.lower()
    mapping = {
        'second': 'seconds',
        'seconds': 'seconds',
        'minute': 'minutes',
        'minutes': 'minutes',
        'hour': 'hours',
        'hours': 'hours',
        'day': 'days',
        'days': 'days',
        'week': 'weeks',
        'weeks': 'weeks',
    }

    if unit not in mapping:
        raise ValueError(f"Frequency unit '{unit}' is not recognized.")

    kwargs = {mapping[unit]: value}
    return datetime.timedelta(**kwargs)

