    if isinstance(matcher, str):
        if ':' in matcher:
            name, default = matcher.split(':', 1)
        else:
            name, default = matcher, None
    else:
        # Try to introspect the matcher object
        name = getattr(matcher, 'name', None)
        default = getattr(matcher, 'default', None)
        if name is None:
            raise ValueError('Matcher must provide a name')
    # Retrieve from environment
    value = os.getenv(name)
    if value is None:
        if default is None:
            raise ValueError(f"Environment variable '{name}' is not set and no default provided")
        return default
    return value

