    if dumper is None:
        dumper = yaml.SafeDumper

    # Dump the object to a string with block style for readability
    # Use default_flow_style=False to force multi-line block scalars
    text = yaml.dump(obj, Dumper=dumper, default_flow_style=False)

    # In Python 2, yaml.dump returns a byte string; convert to unicode
    if isinstance(text, bytes):
        try:
            # Try decoding using UTF-8 which is the default for yaml
            return text.decode('utf-8')
        except (AttributeError, UnicodeDecodeError):
            # Fallback: return the raw byte string (may contain non-ASCII)
            return text
    # In Python 3, the result is already a str
    return text

