            with open(filename, 'r') as f:
                content = f.read()

            if resolve_env:
                env = __import__('os').environ
                content = __import__('re').sub(
                    r'\${([^}]+)}',
                    lambda m: env.get(m.group(1), ''),
                    content
                )

            data = __import__('json').loads(content)

            if overrides:
                def deep_update(target, source):
                    for key, value in source.items():
                        if isinstance(value, dict) and isinstance(target.get(key), dict):
                            deep_update(target[key], value)
                        else:
                            target[key] = value
                deep_update(data, overrides)

            configs[filename] = data

        except Exception as exc:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(exc),
                args=None,
                exc_info=None
            )
            errors.append(record)

    return configs, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
      - dict of configuration filename to corresponding parsed configuration,
      - sequence of logging.LogRecord instances containing any parse errors.
    """
    config_dict = {}
    # Define a handler that collects log records
    class _ListHandler(logging.Handler):
        def __init__(self):
            super().__init__()
            self.records = []

        def emit(self, record):
            self.records.append(record)

    logger = logging.getLogger(__name__)
    handler = _ListHandler()
    logger.addHandler(handler)
    logger.setLevel(logging.ERROR)

    try:
        import json, os, re
        try:
            import yaml  # optional dependency for YAML support
        except ImportError:
            yaml = None

        for fname in config_filenames:
            try:
                with open(fname, "r", encoding="utf-8") as f:
                    content = f.read()
                # Attempt JSON parsing first
                try:
                    data = json.loads(content)
                except Exception:
                    if yaml is None:
                        raise
                    data = yaml.safe_load(content)

                if resolve_env:
                    # Resolve ${VAR} placeholders recursively
                    env_re = re.compile(r"\$\{([^}]+)\}")

                    def _resolve(val):
                        if isinstance(val, str):
                            return env_re.sub(lambda m: os.getenv(m.group(1), ""), val)
                        if isinstance(val, dict):
                            return {k: _resolve(v) for k, v in val.items()}
                        if isinstance(val, list):
                            return [_resolve(v) for v in val]
                        return val

                    data = _resolve(data)

                # Apply overrides if provided (shallow or deep merge)
                if overrides:

                    def _merge(target, src):
                        for key, val in src.items():
                            if isinstance(val, dict) and isinstance(target.get(key), dict):
                                _merge(target[key], val)
                            else:
                                target[key] = val

                    _merge(data, overrides)

                config_dict[fname] = data

            except Exception as exc:
                # Capture failure as a LogRecord without propagating
                logger.error(f"Error loading configuration '{fname}': {exc}", exc_info=exc)
    finally:
        logger.removeHandler(handler)

    return config_dict, handler.records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, os
    try:
        import yaml
    except Exception:
        yaml = None

    config_dict = {}
    error_records = []

    def _expand_env(value):
        if isinstance(value, str):
            return os.path.expandvars(value)
        elif isinstance(value, dict):
            return {k: _expand_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_expand_env(v) for v in value]
        else:
            return value

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
            config_data = None
            # Try YAML first
            if yaml is not None:
                try:
                    config_data = yaml.safe_load(content)
                except Exception:
                    config_data = None
            if config_data is None:
                try:
                    config_data = json.loads(content)
                except Exception as e:
                    raise ValueError(f"Failed to parse {filename} as YAML or JSON: {e}")
            if config_data is None:
                config_data = {}
            if isinstance(config_data, dict):
                # apply overrides if provided
                if overrides:
                    for k, v in overrides.items():
                        if k in config_data and isinstance(config_data[k], dict) and isinstance(v, dict):
                            config_data[k].update(v)
                        else:
                            config_data[k] = v
                # resolve environment variables
                if resolve_env:
                    config_data = _expand_env(config_data)
                config_dict[filename] = config_data
            else:
                raise ValueError(f"Configuration in {filename} does not contain a dictionary at top level")
        except Exception as e:
            logger = logging.getLogger(__name__)
            # Create a LogRecord manually
            record = logging.LogRecord(
                name=logger.name,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(e),
                args=(),
                exc_info=None
            )
            error_records.append(record)

    return config_dict, error_records

