@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple or None")
        # Assume a class attribute `HANDLERS` mapping version tuples to handler classes
        if protocol_version:
            handler = cls.HANDLERS.get(protocol_version)
            return {protocol_version: handler} if handler is not None else {}
        return dict(cls.HANDLERS)

@classmethod
def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    obj = cls()
    if not hasattr(obj, 'bookmarks'):
        obj.bookmarks = []
    for raw in values:
        if not raw:
            continue
        try:
            bookmark = Bookmark.from_raw(raw)
        except Exception:
            bookmark = raw
        obj.bookmarks.append(bookmark)
    return obj

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, (list, tuple, set, dict)):
        seq_ = seq
    else:
        seq_ = list(seq)
    return seq_, type(seq_)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type)."""
    if seq is None:
        return None, None

    # If seq is already a concrete sequence (list, tuple, set, frozenset, str or bytes),
    # we can use it directly. For str/bytes we treat each character/byte as an element.
    if isinstance(seq, (list, tuple, set, frozenset)):
        sequence = seq
    elif isinstance(seq, (str, bytes)):
        # Treat each character/byte as an element.
        sequence = list(seq)
    elif hasattr(seq, "__iter__") or hasattr(seq, "__next__"):
        # For iterables that are not sequences, we need to materialise them.
        # Use bufsize to limit if specified.
        if bufsize is not None:
            from itertools import islice
            sequence = list(islice(seq, bufsize))
        else:
            sequence = list(seq)
    else:
        raise TypeError("The provided object is not iterable")

    # Determine the element type.
    elem_type = None
    for item in sequence:
        if item is not None:
            elem_type = type(item)
            break

    return sequence, elem_type

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Standard sequence types
    if isinstance(seq, (list, tuple, str, bytes, bytearray)):
        return seq, type(seq)

    # Iterable but not a standard sequence
    if hasattr(seq, "__iter__"):
        if bufsize is None:
            seq_list = list(seq)
        else:
            seq_list = []
            it = iter(seq)
            try:
                for _ in range(bufsize):
                    seq_list.append(next(it))
            except StopIteration:
                pass
        return seq_list, type(seq_list)

    # Not iterable – wrap into a single-element list
    return [seq], type([seq])

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a container that implements the Sequence protocol,
    # we can use it as is.  We accept list, tuple, set, frozenset and any
    # user defined sequence type.  For non‑sequence objects we convert to
    # a list.  The `type` returned is the type of the input *seq*.
    # The `bufsize` argument is kept for compatibility but is unused in
    # this simple implementation.
    if isinstance(seq, (list, tuple, set, frozenset)):
        return seq, type(seq)
    try:
        # try to convert iterable to a list
        seq_list = list(seq)
    except TypeError:
        # if seq is not iterable, just return it as a singleton list
        seq_list = [seq]
    return seq_list, type(seq)

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before,
    it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram
    one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Return or compute the cached scale
    if other is None:
        if not hasattr(self, "_scale") or recompute:
            # Compute the integral (total count)
            try:
                if hasattr(self, "counts"):
                    total = sum(self.counts)
                elif hasattr(self, "data"):
                    if isinstance(self.data, dict):
                        total = sum(self.data.values())
                    else:
                        total = sum(self.data)
                else:
                    # Assume the histogram itself is iterable of counts
                    total = sum(self)
            except Exception:
                total = 0
            self._scale = total
        return self._scale

    # Rescaling path: *other* is a numeric target scale
    if not hasattr(self, "_scale") or self._scale == 0:
        raise LenaValueError("cannot rescale histogram with zero scale")
    factor = float(other) / float(self._scale)

    # Apply factor to all bins
    if hasattr(self, "counts"):
        self.counts = [c * factor for c in self.counts]
    elif hasattr(self, "data"):
        if isinstance(self.data, dict):
            self.data = {k: v * factor for k, v in self.data.items()}
        else:
            self.data = [v * factor for v in self.data]
    else:
        # Fallback: iterate over histogram and modify if possible
        try:
            for i, val in enumerate(self):
                # Attempt to modify via __setitem__ or attribute
                if isinstance(self, dict):
                    self[i] = val * factor
                else:
                    # If histogram is a list or similar
                    self[i] = val * factor
        except Exception:
            raise NotImplementedError("Rescaling not implemented for this histogram type")

    # Update the cached scale
    self._scale = other
    return None

def scale(self, other=None, recompute=False):
        """Compute or set scale (integral of the histogram).

        If *other* is ``None``, return scale of this histogram.
        If its scale was not computed before,
        it is computed and stored for subsequent use
        (unless explicitly asked to *recompute*).
        Note that after changing (filling) the histogram
        one must explicitly recompute the scale
        if it was computed before.

        If a float *other* is provided, rescale self to *other*.

        Histograms with scale equal to zero can't be rescaled.
        :exc:`.LenaValueError` is raised if one tries to do that.
        """
        # helper to compute integral from internal storage
        def _compute_scale():
            # try common representations
            if hasattr(self, "_counts"):
                return sum(self._counts)
            elif hasattr(self, "_data"):
                return sum(self._data.values())
            elif hasattr(self, "_bins"):
                return sum(self._bins)
            else:
                # no information available
                return 0

        if other is None:
            # Return stored value if available and not recomputing
            if hasattr(self, "_scale") and not recompute:
                return self._scale
            # compute and store
            self._scale = _compute_scale()
            return self._scale

        # -- rescaling part ----------------------------------------------------
        if not isinstance(other, (int, float)):
            raise TypeError("Scale must be a number when rescaling")
        # ensure current scale is known and non-zero
        current_scale = self.scale(recompute=recompute)
        if current_scale == 0:
            raise LenaValueError("Histogram has zero scale and cannot be rescaled")

        factor = other / current_scale

        # apply factor to all stored counts
        if hasattr(self, "_counts"):
            self._counts = [cnt * factor for cnt in self._counts]
        elif hasattr(self, "_data"):
            self._data = {k: v * factor for k, v in self._data.items()}
        elif hasattr(self, "_bins"):
            self._bins = [b * factor for b in self._bins]
        # else: nothing to scale

        # store new scale
        self._scale = other
        return self._scale

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    if make_value is None:
        make_value = lambda v: v

    # Determine the scale for the output graph
    if scale is True:
        hist_scale = getattr(hist, "scale", None)
    else:
        hist_scale = scale

    points = []

    # Helper to retrieve coordinates for a bin
    def _get_coord(edges, idx, mode):
        left = edges[idx]
        right = edges[idx + 1]
        if mode == "left":
            return left
        if mode == "right":
            return right
        # middle
        return (left + right) / 2.0

    # Case 1: histogram provides an explicit list of bins
    if hasattr(hist, "bins"):
        for bin_obj in hist.bins:
            # Detect bin representation
            if hasattr(bin_obj, "left") and hasattr(bin_obj, "right") and hasattr(bin_obj, "content"):
                left = bin_obj.left
                right = bin_obj.right
                content = bin_obj.content
                if get_coordinate == "left":
                    coord = left
                elif get_coordinate == "right":
                    coord = right
                else:
                    coord = (left + right) / 2.0
            else:
                # Assume a tuple (left, right, content) or (content,) with no context
                tup = tuple(bin_obj) if isinstance(bin_obj, (list, tuple)) else (bin_obj,)
                if len(tup) == 3:
                    left, right, content = tup
                    if get_coordinate == "left":
                        coord = left
                    elif get_coordinate == "right":
                        coord = right
                    else:
                        coord = (left + right) / 2.0
                else:
                    # Only content given, use index as coordinate placeholder
                    coord = 0
                    content = tup[0]

            vals = make_value(content)
            if not isinstance(vals, (tuple, list)):
                vals = (vals,)
            # Ensure match with field names
            point = {field_names[0]: coord}
            for i, val in enumerate(vals):
                if i + 1 < len(field_names):
                    point[field_names[i + 1]] = val
            points.append(point)

    # Case 2: histogram has edges and values (numpy-like)
    elif hasattr(hist, "edges") and hasattr(hist, "values"):
        edges = hist.edges
        values = hist.values
        # Support scalar or 1D arrays as edges attribute
        if isinstance(edges, (list, tuple)):
            edge0 = edges[0]
        elif hasattr(edges, "__array__"):
            edge0 = edges
        else:
            raise AttributeError("Histogram must expose edges and values")
        n_bins = len(edge0) - 1
        # Flatten values for multi-dimensional data
        flat_vals = values.ravel()
        if flat_vals.size != n_bins:
            # If multi-dimensional, take mean over other axes
            flat_vals = values.mean(axis=tuple(range(values.ndim - 1))).ravel()
            if flat_vals.size != n_bins:
                raise ValueError("Histogram shape mismatch with edges")
        for idx in range(n_bins):
            coord = _get_coord(edge0, idx, get_coordinate)
            vals = make_value(flat_vals[idx])
            if not isinstance(vals, (tuple, list)):
                vals = (vals,)
            point = {field_names[0]: coord}
            for i, val in enumerate(vals):
                if i + 1 < len(field_names):
                    point[field_names[i + 1]] = val
            points.append(point)

    # Case 3: histogram is a plain Numpy array
    elif hasattr(hist, "ravel"):
        values = hist.ravel()
        n_bins = values.size
        # In this simple case we assign sequential indices as coordinates
        for idx, val in enumerate(values):
            coord = idx
            vals = make_value(val)
            if not isinstance(vals, (tuple, list)):
                vals = (vals,)
            point = {field_names[0]: coord}
            for i, v in enumerate(vals):
                if i + 1 < len(field_names):
                    point[field_names[i + 1]] = v
            points.append(point)

    else:
        raise TypeError("Unsupported histogram type")

    # Construct result as a simple dictionary mimicking a graph object
    graph = {"scale": hist_scale, "points": points}
    return graph

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Resolve scale
    if scale is True:
        scale_val = getattr(hist, "scale", None)
    else:
        scale_val = scale

    # Create graph instance
    graph = Graph(field_names=field_names, scale=scale_val)

    # Helper to extract coordinate
    if get_coordinate == "left":
        def get_coord(b):
            return getattr(b, "left", getattr(b, "lower", None))
    elif get_coordinate == "right":
        def get_coord(b):
            return getattr(b, "right", getattr(b, "upper", None))
    elif get_coordinate == "middle":
        def get_coord(b):
            left = getattr(b, "left", getattr(b, "lower", 0))
            right = getattr(b, "right", getattr(b, "upper", 0))
            return (left + right) / 2
    else:
        raise ValueError(f"Invalid get_coordinate value: {get_coordinate!r}")

    # Helper to get bin content
    def get_bin_content(b):
        if hasattr(b, "content"):
            return b.content
        if hasattr(b, "value"):
            return b.value
        return b

    # Iterate through histogram bins
    for bin_ in hist:
        coord = get_coord(bin_)
        content = get_bin_content(bin_)
        val = make_value(content) if make_value else content
        if isinstance(val, (tuple, list)):
            point = (coord,) + tuple(val)
        else:
            point = (coord, val)

        # Add the point to the graph
        if hasattr(graph, "add_point"):
            graph.add_point(*point)
        elif hasattr(graph, "add"):
            graph.add(*point)
        else:
            # Fallback: if graph is a simple list
            try:
                graph.append(point)
            except AttributeError:
                # Cannot add point
                pass

    return graph

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*.

    Parameters:
        iface: The interface or base class that *candidate* should provide.
        candidate: The class or instance to be verified.
        tentative (bool): If True, the function will return ``False`` instead of
                          raising an exception when the candidate does not
                          satisfy the interface.

    Returns:
        bool: ``True`` if *candidate* satisfies *iface*, otherwise ``False``
              (or an exception if ``tentative`` is ``False``).
    """
    # First check for the common case where both iface and candidate are
    # classes (including ABCs). In that situation a simple ``issubclass``
    # suffices.
    if isinstance(candidate, type) and isinstance(iface, type):
        ok = issubclass(candidate, iface)
    else:
        # For duck-typing we fall back to checking that all public attributes
        # of the interface exist on the candidate.
        try:
            # If the interface is a typing.Protocol or has __abstractmethods__,
            # use those as the required attributes.
            if hasattr(iface, "__abstractmethods__"):
                required = set(iface.__abstractmethods__)
            else:
                required = {
                    name
                    for name in dir(iface)
                    if not name.startswith("_")
                    and callable(getattr(iface, name, None))
                }
        except Exception:
            # In case iface is not a class-like object, consider all
            # attributes that the candidate actually has.
            required = set(dir(iface)) if not isinstance(iface, type) else set()

        ok = all(hasattr(candidate, attr) for attr in required)

    if not ok:
        if tentative:
            return False
        raise TypeError(f"Candidate {candidate!r} does not provide interface {iface}")

    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    if not isinstance(iface, type):
        raise TypeError("iface must be a class")
    if not isinstance(candidate, type):
        raise TypeError("candidate must be a class")
    if issubclass(candidate, iface):
        return True
    if tentative:
        return False
    raise TypeError(f"{candidate.__name__} does not implement interface {iface.__name__}")

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    if iface is None or candidate is None:
        return False
    # If iface is a concrete class, check isinstance
    try:
        if isinstance(iface, type):
            return isinstance(candidate, iface)
    except Exception:
        pass
    # Otherwise treat iface as an interface-like object and check attributes/methods
    for name in dir(iface):
        if name.startswith('_'):
            continue
        iface_attr = getattr(iface, name)
        if callable(iface_attr):
            if not hasattr(candidate, name) or not callable(getattr(candidate, name)):
                if tentative:
                    continue
                return False
        else:
            if not hasattr(candidate, name):
                if tentative:
                    continue
                return False
    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the candidate might correctly provide iface."""
    # Determine if candidate is a class or an instance
    if isinstance(candidate, type):
        # candidate is a class
        res = issubclass(candidate, iface)
    else:
        # candidate is an instance
        res = isinstance(candidate, iface)

    if res:
        return True

    if tentative:
        # Perform a simple duck-typing check: the candidate must have all
        # attributes (excluding special dunder methods) that iface defines.
        required_attrs = [attr for attr in dir(iface)
                          if not (attr.startswith('__') and attr.endswith('__'))]
        for attr in required_attrs:
            if not hasattr(candidate, attr):
                return False
        return True

    return False

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    if not isinstance(iface, type):
        raise TypeError("iface must be a class or type")
    # Determine the type from candidate
    if isinstance(candidate, type):
        candidate_type = candidate
    else:
        candidate_type = candidate.__class__
    # First try subclass check
    try:
        if issubclass(candidate_type, iface):
            return True
    except TypeError:
        pass
    # If not subclass, try attribute/method check
    missing = []
    for name, member in dir(iface):
        if name.startswith('_'):  # ignore private/protected members
            continue
        if not hasattr(candidate_type, name):
            missing.append(name)
    if missing:
        if tentative:
            return False
        raise AttributeError(
            f"{candidate!r} does not implement required members of {iface.__name__}: "
            + ", ".join(missing)
        )
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # If an explicit metaclass is supplied, it wins.
    if explicit_mc is not None:
        return explicit_mc

    # Gather the metaclasses of all non-None bases.
    metaclasses = set(type(b) for b in bases if b is not None)

    # If there are no bases or all bases have no custom metaclass, default to `type`.
    if not metaclasses:
        return type
    if len(metaclasses) == 1:
        return metaclasses.pop()

    # If multiple metaclasses are present, try to find one that
    # is a subclass of all others. This is the "most-derived" metaclass.
    chosen = None
    for candidate in metaclasses:
        if all(issubclass(candidate, others) for others in metaclasses):
            if chosen is not None and chosen is not candidate:
                # Ambiguous: more than one suitable candidate.
                break
            chosen = candidate

    if chosen is None:
        raise TypeError(
            "metaclass conflict: metaclass conflict among bases: "
            + ", ".join(m.__name__ for m in sorted(metaclasses, key=lambda c: c.__name__))
        )

    return chosen

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if not bases:
        return type
    # Collect candidate metaclasses
    candidates = [explicit_mc] if explicit_mc is not None else []
    candidates += [type(b) for b in bases]
    # Find the most derived candidate
    mc = candidates[0]
    for c in candidates[1:]:
        if issubclass(c, mc):
            mc = c
        elif not issubclass(mc, c):
            raise TypeError(f"metaclass conflict: {c} is not a subclass of {mc}")
    return mc

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If a metaclass is explicitly requested, use it.
    if explicit_mc is not None:
        return explicit_mc

    # No bases -> the default metaclass is 'type'
    if not bases:
        return type

    # Collect the metaclasses of all bases.
    metaclasses = {type(b) for b in bases}

    # If only one metaclass, that's the effective metaclass.
    if len(metaclasses) == 1:
        return metaclasses.pop()

    # Attempt to find the most derived metaclass that is a subclass
    # of every other base metaclass.
    result = None
    for m in metaclasses:
        if result is None:
            result = m
            continue
        if issubclass(m, result):
            result = m
        elif not issubclass(result, m):
            # No clear subtyping relationship: conflict.
            base_names = ', '.join(b.__name__ for b in bases)
            raise TypeError(
                f"metaclass conflict: {m} vs {result} when creating class from ({base_names})"
            )
    return result

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # If an explicit metaclass is supplied, use that
    if explicit_mc is not None:
        return explicit_mc

    # Derive metaclasses from bases
    metaclasses = [type(b) for b in bases]

    # If no bases, default to 'type'
    if not metaclasses:
        return type

    # If only one metaclass, use it
    if len(set(metaclasses)) == 1:
        return metaclasses[0]

    # Find a metaclass that is a superclass of all others (most derived)
    for candidate in metaclasses:
        if all(issubclass(other, candidate) for other in metaclasses):
            return candidate

    # If none of the above, fall back to Python's default metaclass
    return type

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        res = self[key]
        del self[key]
        return res
    except KeyError:
        if default is __marker:
            raise KeyError(key)
        return default

