        return value
    except KeyError:
        if default is __marker:
            raise
        return default

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Raise KeyError if the container is empty
    if not self:
        raise KeyError('popitem(): dictionary is empty')
    # Find the key with the smallest usage count.  If the
    # container tracks usage in a `_freq` dictionary, we use that;
    # otherwise we just pop an arbitrary key.
    try:
        # Assume an internal dict mapping key -> count is available
        min_key = min(self._freq, key=lambda k: self._freq[k])
    except AttributeError:
        # Fallback: just pop the first key (e.g. when no frequency data)
        min_key = next(iter(self))
    value = self.pop(min_key)
    return min_key, value

