def _create_in_regex(self) -> Pattern:
    """Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    # Compile a regex that matches an 'in' parameter in the form: in="value"
    # or in='value' or in=value, optionally surrounded by whitespace.
    return re.compile(
        r'\bin\b\s*=\s*(?P<value>"[^"]*"|\'[^\']*\'|[^,\s]+)',
        re.IGNORECASE,
    )

def _create_in_regex(self) -> Pattern:
    """Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    pattern = r"\bin\s*=\s*['\"]([^'\"]+)['\"]"
    return re.compile(pattern, re.IGNORECASE)

