def isoparse(self, dt_str):
        """Parse an ISO-8601 datetime string into a :class:`datetime.datetime`.

        See the class documentation for a full description of supported
        formats.
        """
        import re
        from datetime import datetime, date, time, timezone
        try:
            # lazily import dateutil.tz if available
            from dateutil.tz import tzoffset, tzutc
        except Exception:
            tzoffset = None
            tzutc = None

        if not isinstance(dt_str, (str, bytes)):
            raise TypeError("dt_str must be a string or bytes")
        if isinstance(dt_str, bytes):
            dt_str = dt_str.decode('ascii')

        dt_str = dt_str.strip()

        # Split date/time using the official separator 'T' or 't'
        if 't' in dt_str or 'T' in dt_str:
            date_part, rest = re.split(r'[tT]', dt_str, maxsplit=1)
        else:
            date_part, rest = dt_str, ''

        # Parse date
        year = month = day = None
        week = weekday = None
        # Common formats
        m = re.match(r'^(?P<year>\d{4})$', date_part)
        if m:
            year = int(m.group('year'))
        else:
            m = re.match(r'^(?P<year>\d{4})-?(?P<month>\d{2})-?(?P<day>\d{2})$', date_part)
            if m:
                year = int(m.group('year'))
                month = int(m.group('month'))
                day = int(m.group('day'))
            else:
                m = re.match(r'^(?P<year>\d{4})-?(?P<month>\d{2})$', date_part)
                if m:
                    year = int(m.group('year'))
                    month = int(m.group('month'))
                    day = 1
                else:
                    # ISO week formats
                    m = re.match(r'^(?P<year>\d{4})[ -]?(?P<week_indicator>[Ww])(?P<week>\d{2})$', date_part)
                    if m:
                        year = int(m.group('year'))
                        week = int(m.group('week'))
                        weekday = 1
                    else:
                        m = re.match(r'^(?P<year>\d{4})[ -]?(?P<week_indicator>[Ww])(?P<week>\d{2})[ -]?(?P<weekday>\d)$', date_part)
                        if m:
                            year = int(m.group('year'))
                            week = int(m.group('week'))
                            weekday = int(m.group('weekday'))
                        else:
                            raise ValueError("Invalid ISO date format: %s" % date_part)

        # Handle incomplete dates
        if year is None:
            raise ValueError("Missing year in ISO date")
        if week is not None:
            # year, week, weekday (default 1)
            try:
                d = date.fromisocalendar(year, week, weekday)
            except Exception as exc:
                raise ValueError("Invalid ISO week date: %s" % date_part) from exc
        else:
            if month is None:
                month = 1
            if day is None:
                day = 1
            try:
                d = date(year, month, day)
            except Exception as exc:
                raise ValueError("Invalid ISO date: %s" % date_part) from exc

        # Default tzinfo to None
        tzinfo = None

        if rest:
            # Time part and optional tz
            # Separate time and tz
            # Find tz part: matches Z, +HH:MM, +HHMM, or +HH
            tz_match = re.search(r'(Z|[+\-]\d{2}(:?\d{2})?|\+[0-9]{2}|-[0-9]{2})$', rest)
            if tz_match:
                tz_str = tz_match.group(0)
                time_part = rest[:-len(tz_str)]
            else:
                tz_str = ''
                time_part = rest

            # Parse time
            tm = re.match(r'^(?P<hour>\d{2})'            # hour
                          r'(?:[.,](?P<minute>\d{2})'   # minute
                          r'(?:[.,](?P<second>\d{2})'   # second
                          r'(?:[.,](?P<frac>\d{1,6}))?'
                          r')?)?)?$', time_part)
            if not tm:
                raise ValueError("Invalid ISO time format: %s" % time_part)
            hour = int(tm.group('hour'))
            minute = int(tm.group('minute') or 0)
            second = int(tm.group('second') or 0)
            frac = tm.group('frac')
            microsecond = 0
            if frac:
                # Pad to 6 digits
                microsecond = int(frac.ljust(6, '0'))

            # Handle special 24:00 case
            if hour == 24:
                if minute != 0 or second != 0:
                    raise ValueError("Illegal 24-hour time with minutes or seconds")
                hour = 0
                d = d + timedelta(days=1)

            t = time(hour, minute, second, microsecond)

            # Resolve tzinfo
            if tz_str == '':
                tzinfo = None
            elif tz_str == 'Z':
                tzinfo = tzutc()
            else:
                sign = 1 if tz_str[0] == '+' else -1
                tz_numbers = tz_str[1:].replace(':', '')
                if len(tz_numbers) == 2:
                    hrs = int(tz_numbers)
                    mins = 0
                elif len(tz_numbers) == 4:
                    hrs = int(tz_numbers[:2])
                    mins = int(tz_numbers[2:])
                else:
                    raise ValueError("Invalid time zone offset: %s" % tz_str)
                offset = sign * (hrs * 3600 + mins * 60)
                if tzoffset and tzutc:
                    # Use dateutil.tz if available
                    if offset == 0:
                        tzinfo = tzutc()
                    else:
                        tzinfo = tzoffset(None, offset)
                else:
                    tzinfo = timezone(timedelta(seconds=offset))

            return datetime.combine(d, t, tzinfo=tzinfo)
        else:
            # No time part, return date as midnight without tzinfo
            return datetime.combine(d, time(0, 0))

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Public message check
    if getattr(request, "public", None):
        public = request.public
        if isinstance(public, dict) and public.get("diaspora") is True:
            return True

    # Private message check
    if getattr(request, "private", None):
        private = request.private
        if isinstance(private, dict) and private.get("diaspora") is True:
            return True

    # Legacy payload check
    try:
        legacy = request.legacy_payload
        if isinstance(legacy, dict) and legacy.get("type") == "diaspora":
            return True
        if isinstance(legacy, str) and "Diaspora" in legacy:
            return True
    except Exception:
        pass

    return False

