def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    # Ensure no microseconds in the formatted string
    if hasattr(dt, "tzinfo") and dt.tzinfo is not None:
        # Use ISO format, which includes the timezone info
        return dt.replace(microsecond=0).isoformat()
    else:
        # Naive datetime – use a compact ISO 8601 style without fractional seconds
        return dt.replace(microsecond=0).strftime("%Y-%m-%dT%H:%M:%S")

