def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """

    # Validate inputs
    if not public_key:
        raise ValueError("Public key must be provided")
    if not signature:
        raise ValueError("Signature must be provided")

    # Ensure doc is an XML Element; if string parse it
    if isinstance(doc, str):
        try:
            from lxml import etree
            root = etree.fromstring(doc)
        except Exception as e:
            raise ValueError("Provided doc is not valid XML") from e
    else:
        root = doc

    # Find the Signature element (XMLDSIG namespace)
    try:
        from lxml import etree
        ns = {'ds': 'http://www.w3.org/2000/09/xmldsig#'}
        sig_element = root.find('.//ds:Signature', namespaces=ns)
    except Exception:
        raise ValueError("Signature element not found in XML")

    if sig_element is None:
        raise ValueError("No Signature element found in the document")

    # Verify using xmlsec
    try:
        import xmlsec
        ctx = xmlsec.SignatureContext()
        # Load the public key in PEM format
        key = xmlsec.Key.from_memory(public_key, xmlsec.KeyFormat.PEM, None)
        ctx.key = key
        # Perform verification – this raises if verification fails
        ctx.verify(sig_element)
    except Exception as exc:
        raise ValueError("XML signature verification failed") from exc

    # If verification succeeded, return True
    return True

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Try JSON first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            return data
    except Exception:
        pass  # Not JSON, fall back to XRD parsing

    # XRD parsing
    try:
        root = ET.fromstring(document)
    except ET.ParseError as e:
        raise ValueError("Cannot parse webfinger document as JSON or XRD") from e

    def local(tag):
        return tag.split('}', 1)[-1] if '}' in tag else tag

    result: Dict[str, object] = {}

    # Extract <Subject>
    for child in root:
        if local(child.tag) == 'Subject':
            result['subject'] = child.text
            break

    # Extract <Link> elements
    links = []
    for link in root.findall('.//*'):
        if local(link.tag) == 'Link':
            attrs = {}
            for attr in ['rel', 'type', 'href', 'template', 'name', 'profile']:
                if link.get(attr) is not None:
                    attrs[attr] = link.get(attr)
            if attrs:
                links.append(attrs)

    if links:
        result['links'] = links

    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    def _strip_ns(tag: str) -> str:
        return tag.split("}", 1)[-1] if "}" in tag else tag

    # Attempt JSON parsing first
    try:
        data = json.loads(document)
    except Exception:
        # Fallback to XML parsing (XRD)
        try:
            root = ET.fromstring(document)
        except ET.ParseError:
            raise ValueError("Unable to parse document as either JSON or XRD")
        subject = None
        aliases = []
        links = []

        for elem in root.iter():
            name = _strip_ns(elem.tag)
            if name == "Subject":
                subject = elem.text
            elif name == "Alias":
                if elem.text:
                    aliases.append(elem.text)
            elif name == "Link":
                rel = elem.attrib.get("rel")
                type_ = elem.attrib.get("type")
                href = elem.attrib.get("href")
                if href:
                    links.append({"rel": rel, "type": type_, "href": href})
        return {"subject": subject, "aliases": aliases, "links": links}

    # If JSON parsed successfully
    subject = data.get("subject")
    aliases = data.get("aliases", [])
    raw_links = data.get("links", [])
    links = []
    for l in raw_links:
        rel = l.get("rel")
        type_ = l.get("type")
        href = l.get("href")
        if href:
            links.append({"rel": rel, "type": type_, "href": href})
    return {"subject": subject, "aliases": aliases, "links": links}

def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # First attempt to parse as JSON (new format)
    try:
        data = json.loads(document)
    except json.JSONDecodeError:
        data = None

    if data is not None:
        result: Dict[str, str] = {}
        result["subject"] = data.get("subject", "")
        for link in data.get("links", []):
            rel = link.get("rel")
            if not rel:
                continue
            href = link.get("href") or link.get("template")
            if href:
                result[rel] = href
        return result

    # Fallback: try parsing as XRD (old format)
    try:
        root = ET.fromstring(document)
    except ET.ParseError as exc:
        raise ValueError("Input document is neither valid JSON nor valid XRD XML") from exc

    # Namespace handling: XRD elements may have a default namespace
    ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"} if root.tag.startswith("{") else {}

    def find(q):
        return root.find(q, ns)

    result: Dict[str, str] = {}
    subject_elem = find(".//xrd:Subject") or find(".//Subject")
    if subject_elem is not None and subject_elem.text:
        result["subject"] = subject_elem.text.strip()

    for link in root.findall(".//xrd:Link", ns) or root.findall(".//Link"):
        rel = link.attrib.get("rel")
        if not rel:
            continue
        href = link.attrib.get("href") or link.attrib.get("template")
        if href:
            result[rel] = href.strip()

    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Try JSON first
    try:
        parsed = json.loads(document)
        # If JSON is an array, we assume the first element is the relevant object
        if isinstance(parsed, list) and parsed:
            parsed = parsed[0]
        return parsed
    except Exception:
        pass

    # Fallback to XRD (XML) parsing
    try:
        root = ET.fromstring(document)
    except ET.ParseError:
        return {}

    ns = {'xrd': "http://docs.oasis-open.org/ns/xri/xrd-1.0"}

    def findtext(elem, tag):
        t = elem.find(f"{{{ns['xrd']}}}{tag}") or elem.find(tag)
        return t.text if t is not None else None

    def findall(elem, tag):
        return elem.findall(f"{{{ns['xrd']}}}{tag}") or elem.findall(tag)

    subject = findtext(root, "Subject")
    aliases = [a.text for a in findall(root, "Alias") if a.text]
    links = []
    for link in findall(root, "Link"):
        rel = link.attrib.get("rel")
        href = link.attrib.get("href")
        type_ = link.attrib.get("type")
        if rel and href:
            item = {"rel": rel, "href": href}
            if type_:
                item["type"] = type_
            links.append(item)

    return {"subject": subject, "aliases": aliases, "links": links}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # First try JSON parsing
    try:
        return json.loads(document, strict=False)
    except Exception:
        # Fallback to XRD (XML) parsing
        from xml.etree import ElementTree as ET
        root = ET.fromstring(document)

        def element_to_dict(e):
            d = {}
            # Include element tag
            d[e.tag] = {}
            # Include attributes if any
            if e.attrib:
                d[e.tag].update(e.attrib)
            # Recurse into children
            for child in e:
                d[e.tag].update(element_to_dict(child))
            # Include text content
            if e.text and e.text.strip():
                d[e.tag]['text'] = e.text.strip()
            return d

        return element_to_dict(root)

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
