def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import urllib.request
    import urllib.parse
    import urllib.error
    import json

    if not handle:
        raise ValueError("handle must be provided")

    # Normalize the handle to exclude optional 'acct:' prefix
    if handle.startswith("acct:"):
        acct = handle[5:]
    else:
        acct = handle

    if "@" not in acct:
        raise ValueError(f"Handle '{handle}' must contain '@' to separate local part and domain")

    local, host = acct.split("@", 1)
    resource = f"acct:{local}@{host}"
    url = f"https://{host}/.well-known/webfinger?resource={urllib.parse.quote(resource)}"

    try:
        with urllib.request.urlopen(url) as response:
            if response.status != 200:
                raise ValueError(f"Failed to retrieve webfinger for {handle}: HTTP {response.status}")
            raw = response.read().decode("utf-8")
            return json.loads(raw)
    except urllib.error.URLError as exc:
        raise ValueError(f"Error retrieving webfinger for {handle}: {exc}") from exc

def retrieve_diaspora_host_meta(host):
    """Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    # Possible locations for the host-meta document
    endpoints = [
        f"https://{host}/.well-known/host-meta",
        f"https://{host}/.well-known/host-meta.json",
        f"http://{host}/.well-known/host-meta",
        f"http://{host}/.well-known/host-meta.json",
    ]

    from urllib import request, error
    import socket

    for url in endpoints:
        try:
            req = request.Request(
                url,
                headers={"Accept": "application/xrd+xml"},
            )
            with request.urlopen(req, timeout=10) as resp:
                # Get the raw content as text
                body = resp.read()
                content = body.decode("utf-8")

                # Parse the host-meta XML/JSON into an XRD instance.
                # The `XRD` class is expected to expose a `from_string` method.
                from XRD import XRD  # Assume XRD is available in the environment
                try:
                    return XRD.from_string(content)
                except Exception:
                    # Try to parse JSON representation if applicable
                    try:
                        return XRD.from_json(content)
                    except Exception:
                        pass

        except (error.HTTPError, error.URLError, socket.timeout, ValueError):
            # Try the next endpoint if this one fails
            continue

    # If none of the attempts succeeded, raise an informative error
    raise ValueError(f"Could not retrieve host-meta document from host '{host}'")

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    # Ensure method name is lowercase string to match requests attribute
    if not isinstance(method, str):
        return None, ValueError(f"Method should be a string, got {type(method).__name__}")
    method_name = method.lower()

    # Try to get the requests method function (e.g., requests.post)
    try:
        request_func = getattr(requests, method_name)
    except AttributeError:
        return None, ValueError(f"Unsupported method '{method}'. No such function requests.{method_name}")

    # Send the request and handle errors
    try:
        response = request_func(url, data=data, timeout=timeout, *args, **kwargs)
        return response.status_code, None
    except requests.exceptions.RequestException as exc:
        return None, exc

