def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import fnmatch

    # Normalise settings_dirs to a list
    if isinstance(settings_dirs, str):
        dirs = [settings_dirs]
    else:
        dirs = settings_dirs

    found_files = []

    # Define a function to match spec_option if provided
    def matches(path):
        if spec_option is None:
            return True
        # If spec_option looks like an extension (e.g., ".txt")
        if spec_option.startswith('.'):
            return path.lower().endswith(spec_option.lower())
        # Otherwise treat it as a glob pattern
        return fnmatch.fnmatchcase(os.path.basename(path), spec_option)

    for d in dirs:
        if not os.path.isdir(d):
            continue
        for root, _, files in os.walk(d):
            for fname in files:
                full_path = os.path.join(root, fname)
                if matches(full_path):
                    found_files.append(full_path)

    return sorted(found_files)

def list_of_file_names(settings_dirs, spec_option):
