def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type

    Parameters:
        settings_dirs (Sequence[str]): list of directory paths to search for .ini files
        spec_option (dict): default option values (section/key/value) to ensure exist

    Returns:
        configparser.ConfigParser:  an IniType instance populated from the found files
    """
    import configparser
    import os

    ini = configparser.ConfigParser()
    # read all .ini files from the provided directories
    for dir_path in settings_dirs:
        if not os.path.isdir(dir_path):
            continue
        for fname in os.listdir(dir_path):
            if fname.lower().endswith('.ini'):
                ini.read(os.path.join(dir_path, fname))

    # ensure any spec options are present (under DEFAULT section if not specified)
    for key, value in spec_option.items():
        if key not in ini.defaults():
            ini['DEFAULT'][key] = str(value)

    return ini

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    file_list = []
    for d in settings_dirs:
        if not os.path.isdir(d):
            continue
        for f in os.listdir(d):
            path = os.path.join(d, f)
            if not os.path.isfile(path):
                continue
            if spec_option is None:
                file_list.append(path)
            elif isinstance(spec_option, str):
                if f.endswith(spec_option):
                    file_list.append(path)
            elif callable(spec_option):
                try:
                    if spec_option(f):
                        file_list.append(path)
                except Exception:
                    # If the spec function raises an exception, skip the file
                    continue
    return file_list

