def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    # Helper to recursively resolve include directives in a nested dictionary.
    def _resolve(item):
        if isinstance(item, dict):
            if "include" in item:
                # Resolve included spec file or dictionary.
                # It is up to the concrete implementation to provide
                # `self._load_spec(path)` which returns the parsed dictionary.
                inc_path = item["include"]
                included = self._load_spec(inc_path) if hasattr(self, "_load_spec") else {}
                # Merge included dict into current, with current keys overwriting.
                merged = {**included, **{k: v for k, v in item.items() if k != "include"}}
                return _resolve(merged)
            else:
                return {k: _resolve(v) for k, v in item.items()}
        elif isinstance(item, list):
            return [_resolve(v) for v in item]
        else:
            return item

    return _resolve(parser_dict)

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        import json, os

        def _merge(target, src):
            for k, v in src.items():
                if k in target and isinstance(target[k], dict) and isinstance(v, dict):
                    _merge(target[k], v)
                else:
                    target[k] = v

        def _resolve(d, base_path):
            if isinstance(d, dict):
                # Handle include directive
                if "__include__" in d:
                    inc_path = d.pop("__include__")
                    if not os.path.isabs(inc_path):
                        inc_path = os.path.join(base_path, inc_path)
                    with open(inc_path, "r", encoding="utf-8") as f:
                        inc_data = json.load(f)
                    _merge(d, inc_data)
                    # Resolve includes within the newly merged data
                    _resolve(d, os.path.dirname(inc_path))
                # Resolve nested structures
                for key, val in d.items():
                    _resolve(val, base_path)
            elif isinstance(d, list):
                for item in d:
                    _resolve(item, base_path)

        # Determine the base directory for relative include paths
        base_path = os.path.dirname(os.path.abspath(parser_dict.get("__file__", "")))
        _resolve(parser_dict, base_path)

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    # Many spec files support an ``include`` entry to pull in external
    # group definitions. The include value is expected to be a dictionary
    # that should be merged into the current ``parser_dict``.  The
    # merging is done recursively so that nested groups are handled
    # correctly.  The method operates in-place and raises a ValueError
    # if the ``include`` entry is not a dict.
    include = parser_dict.pop('include', None)
    if include is None:
        return

    if not isinstance(include, dict):
        raise ValueError("'include' directive must be a dictionary")

    def _merge(target, src):
        for key, val in src.items():
            if key in target and isinstance(target[key], dict) and isinstance(val, dict):
                _merge(target[key], val)
            else:
                target[key] = val

    _merge(parser_dict, include)

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    resolved_groups = {}

    def _resolve(group_name, visited):
        if group_name in visited:
            raise ValueError(f"Circular include detected for group '{group_name}'")
        visited.add(group_name)

        if group_name not in parser_dict:
            raise KeyError(f"Group '{group_name}' not found in parser_dict")
        group_def = parser_dict[group_name]
        # Make a shallow copy so the original dict remains unchanged
        local_def = dict(group_def)

        includes = local_def.get('include')
        if includes:
            # Normalise to a list
            if isinstance(includes, str):
                includes = [includes]
            for inc_name in includes:
                inc_def = _resolve(inc_name, visited.copy())
                # Merge content if present
                if isinstance(inc_def, dict):
                    local_def.setdefault('content', []).extend(
                        inc_def.get('content', [])
                    )
                    # Merge additional properties if needed
                    local_def.setdefault('properties', {}).update(
                        inc_def.get('properties', {})
                    )
        return local_def

    for key in parser_dict:
        resolved_groups[key] = _resolve(key, set())

    return resolved_groups

