    # First try a public attribute, then a private one as a fallback.
    deprecation_map = getattr(self, "DEPRECATED_ARGS", None)
    if deprecation_map is None:
        deprecation_map = getattr(self, "_deprecated_args", {})

    # Collect and display deprecation warnings
    warnings = []
    for arg, value in combined_args.items():
        if arg in deprecation_map:
            msg = deprecation_map[arg] if isinstance(deprecation_map[arg], str) else ""
            warnings.append(f"Argument '{arg}' is deprecated{msg and ': ' + msg}")
    for warning in warnings:
        print(warning)

    return warnings

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    deprecated_map = getattr(self, 'DEPRECATED_ARGUMENTS', {})
    for src, args in [('cli', cli_args), ('answer_file', answer_file_args)]:
        for arg in list(args):
            if arg in deprecated_map:
                new_name = deprecated_map[arg]
                print(f"WARNING: Argument '{arg}' from {src} is deprecated; use '{new_name}' instead.")
                # Promote the value to the new argument name if not already present
                if new_name not in args:
                    args[new_name] = args[arg]
                del args[arg]

def validate_arg_deprecation(self, cli_args, answer_file_args):
