        raise TypeError("cli_args and answer_file_args must be dictionaries")

    for source_name, args in [("CLI", cli_args), ("Answer file", answer_file_args)]:
        for arg in list(args.keys()):
            if arg in deprecated_map:
                new_arg = deprecated_map[arg]
                print(f"Warning: Argument '{arg}' from {source_name} is deprecated; use '{new_arg}' instead.")

