def _get_conditionally_required_args(self, command_name, options_spec, args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        required = []
        for opt in options_spec:
            name = opt.get('name')
            if not name:
                continue
            cond = opt.get('required_when')
            if cond is None:
                continue
            match = False
            if callable(cond):
                try:
                    match = bool(cond(args))
                except Exception:
                    match = False
            else:
                # Treat as a string expression. Use args as local namespace.
                try:
                    match = bool(eval(cond, {}, args))
                except Exception:
                    match = False
            if match:
                required.append(name)
        return required

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        conditionals = []

        # Normalise args into a dictionary for evaluation
        if isinstance(args, dict):
            local = args
        else:
            try:
                local = vars(args)
            except Exception:
                local = {}

        for opt in options_spec:
            if 'required_when' in opt:
                cond_expr = opt['required_when']
                try:
                    # Evaluate the condition in a local namespace of the args
                    if eval(cond_expr, {}, local):
                        conditionals.append(opt['name'])
                except Exception:
                    # If evaluation fails (e.g., missing key), ignore the option
                    pass

        return conditionals

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    # Normalise args to something we can test membership on
    arg_set = set()
    if isinstance(args, dict):
        arg_set.update(args.keys())
    else:
        arg_set.update(args)
    for opt in options_spec:
        if 'required_when' not in opt:
            continue
        req = opt['required_when']

        # If required_when is a dict keyed by command name, pick the relevant list
        if isinstance(req, dict):
            if command_name in req:
                req = req[command_name]
            else:
                continue

        # Resolve the optional argument name
        arg_name = opt.get('name') or opt.get('argument')
        if not arg_name:
            continue

        # Evaluate whether the condition is satisfied
        matched = False
        if isinstance(req, (list, tuple, set)):
            # Condition triggers if any of the specified keys are present in args
            matched = any(item in arg_set for item in req)
        else:
            # If a single literal condition, check simple presence
            matched = req in arg_set

        if matched:
            required.append(arg_name)
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict")

    # Determine the maximum allowed length; default to 255 if not defined
    max_len = getattr(self, "max_length", 255)

    for key, value in args.items():
        if isinstance(value, str) and len(value) > max_len:
            raise ValueError(
                f'Argument "{key}" length {len(value)} exceeds maximum of {max_len}'
            )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Determine the mapping of argument names to maximum allowed lengths.
    # Prefer `MAX_LENGTHS` if defined, otherwise fall back to `LENGTHS`.
    length_constraints = {}
    if hasattr(self, "MAX_LENGTHS") and isinstance(self.MAX_LENGTHS, dict):
        length_constraints.update(self.MAX_LENGTHS)
    if hasattr(self, "LENGTHS") and isinstance(self.LENGTHS, dict):
        length_constraints.update(self.LENGTHS)

    # Iterate over each argument and verify its length.
    for key, val in args.items():
        # Skip checks if no constraint is defined for this key.
        max_len = length_constraints.get(key)
        if max_len is None:
            continue

        # Only attempt length checks on objects that provide a length.
        try:
            current_len = len(val)
        except Exception:
            # Skip values where len() is not applicable (e.g. None, int).
            continue

        if current_len > max_len:
            raise ValueError(
                f"Argument '{key}' has length {current_len}, "
                f"which exceeds the maximum allowed length of {max_len}"
            )

    return True

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # `args` is expected to be a mapping of argument names to values.
    # For each argument, if the element defines a corresponding maximum length
    # attribute (`MAX_<ARGNAME>_LEN`), ensure the value does not exceed it.
    # Raise a ValueError if any exceed their limits.
    for name, value in args.items():
        # value may be a string or a sequence; skip if None
        if value is None:
            continue
        max_len = getattr(self, f"MAX_{name.upper()}_LEN", None)
        if max_len is not None:
            try:
                length = len(value)
            except TypeError:
                raise TypeError(f"Argument '{name}' of type {type(value).__name__} is not sized")
            if length > max_len:
                raise ValueError(f"Argument '{name}' length {length} exceeds maximum of {max_len}")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Ensure that the instance has a mapping of argument names to allowed choices.
    if not hasattr(self, "choices") or not isinstance(self.choices, dict):
        raise AttributeError("Instance must provide a 'choices' dictionary mapping argument names to iterable of allowed values.")

    for key, val in args.items():
        # Check if this key has defined choices; if not, skip validation.
        if key in self.choices:
            allowed = self.choices[key]
            if val not in allowed:
                raise ValueError(
                    f"Invalid value for '{key}': {val!r} is not among the allowed choices {allowed!r}."
                )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # The class may define a mapping of attribute names to their allowed
    # values under the attribute ``CHOICES``. If no such mapping is
    # available, this method simply returns.
    allowed_choices = getattr(self.__class__, 'CHOICES', {})

    for attr, value in args.items():
        # Skip attributes that do not have defined choices
        if attr not in allowed_choices:
            continue

        valid_values = allowed_choices[attr]
        # Normalise to a collection for membership testing
        if isinstance(valid_values, (list, tuple, set)):
            if value not in valid_values:
                raise ValueError(
                    f"Invalid value for attribute '{attr}': {value!r}. "
                    f"Allowed choices: {valid_values!r}"
                )
        elif isinstance(valid_values, dict):
            # For dictionaries, keys represent the valid values
            if value not in valid_values:
                raise ValueError(
                    f"Invalid value for attribute '{attr}': {value!r}. "
                    f"Allowed keys: {list(valid_values.keys())!r}"
                )
        else:
            # If the value type is not recognised, skip the check
            continue

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Support both dicts and argparse.Namespace objects
    if isinstance(args, dict):
