    else:
        items = vars(args).items()

    for key, value in items:
        if key in getattr(self, "choices", {}):
            choices = self.choices[key]
            if value not in choices:
                raise ValueError(
                    f"Invalid value for argument '{key}': {value!r}. "
                    f"Allowed choices are: {choices!r}"
