        # Convention: argument name in uppercase followed by _CHOICES
        choices_attr = getattr(self.__class__, name.upper() + "_CHOICES", None)
        if choices_attr is None:
            continue  # No choices defined, skip validation.
        # If the value is an iterable of values, validate each.
        if isinstance(value, (list, tuple, set)):
            for v in value:
                if v not in choices_attr:
                    raise ValueError(
