                        f"Allowed values are {choices_attr}."
                    )
        else:
            if value not in choices_attr:
                raise ValueError(
                    f"Invalid value {value!r} for argument {name!r}. "
                    f"Allowed values are {choices_attr}."
                )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    min_val = getattr(self, 'minimum', None)
    max_val = getattr(self, 'maximum', None)

    # If no bounds are defined, nothing to check
    if min_val is None and max_val is None:
        return

    for val in args:
        if val is None:
            continue
        if min_val is not None and val < min_val:
            raise ValueError(
                f"Argument value {val} is less than the minimum allowed {min_val}."
            )
        if max_val is not None and val > max_val:
            raise ValueError(
                f"Argument value {val} exceeds the maximum allowed {max_val}."
            )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure the arguments are an iterable
    if not isinstance(args, (list, tuple)):
        args = [args]

    # If the instance does not have min or max defined, skip validation
    if not hasattr(self, 'min') or not hasattr(self, 'max'):
        return

    for i, arg in enumerate(args):
        if arg < self.min or arg > self.max:
            raise ValueError(
                f"Argument at index {i} ({arg}) is out of bounds "
                f"[{self.min}, {self.max}]."
            )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Accepts either a sequence
                 (value, min_value, max_value) or a mapping containing
                 the keys 'value', 'min', and 'max'.
    """
    # Accept different input formats for flexibility
    if isinstance(args, (list, tuple)):
        try:
            value, min_val, max_val = args
        except Exception:
            raise ValueError("args sequence must unpack to three elements"
                             " (value, min, max)")
    elif isinstance(args, dict):
        if not all(k in args for k in ("value", "min", "max")):
            raise ValueError("args dict must contain keys 'value', 'min', and 'max'")
        value = args["value"]
        min_val = args["min"]
        max_val = args["max"]
    else:
        raise TypeError("args must be a sequence or a mapping with 'value', "
                        "'min', and 'max' keys")

    # Basic type validation
    if not isinstance(min_val, (int, float)) or not isinstance(max_val, (int, float)):
        raise TypeError("min and max must be numeric types")
    if not isinstance(value, (int, float)):
        raise TypeError("value must be a numeric type")

    if min_val > max_val:
        raise ValueError("Minimum value cannot be greater than maximum value")

    if not (min_val <= value <= max_val):
        raise ValueError(f"Value {value} is outside the range [{min_val}, {max_val}]")

    return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Determine bounds are defined on the instance
    if hasattr(self, 'MIN') and hasattr(self, 'MAX'):
        min_val, max_val = self.MIN, self.MAX
    elif hasattr(self, 'min') and hasattr(self, 'max'):
        min_val, max_val = self.min, self.max
    else:
        # No bounds defined; nothing to validate
        return

    # Determine the iterable of arguments
    if isinstance(args, dict):
        items = args.items()
    else:
        # Assume a sequence of values
        items = enumerate(args)

    # Validate each argument
    for key, val in items:
        if val is None:
            continue  # skip missing values
        try:
            numeric_val = float(val)
        except Exception:
            continue  # skip non-numeric values
        if numeric_val < min_val or numeric_val > max_val:
            arg_name = key if isinstance(args, dict) else f"arg[{key}]"
            raise ValueError(f"Argument {arg_name} value {val} out of bounds [{min_val}, {max_val}]")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    min_args = getattr(self, 'min_args', None)
    max_args = getattr(self, 'max_args', None)

    try:
        count = len(args)
    except TypeError:
        # args is not a sized iterable (e.g., a generator); count lazily
        count = sum(1 for _ in args)

    if min_args is not None and count < min_args:
        raise ValueError(
            f"Too few arguments: expected at least {min_args}, got {count}"
        )

    if max_args is not None and count > max_args:
        raise ValueError(
            f"Too many arguments: expected at most {max_args}, got {count}"
        )

    return True

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    if not args:
        return control_args, nested_args

    # Determine each argument as key/value pair.
    if isinstance(args, dict):
        items = args.items()
    else:
        items = []
        for item in args:
            if isinstance(item, str):
                if '=' not in item:
                    continue
                k, v = item.split('=', 1)
                items.append((k, v))
            elif hasattr(item, '__len__') and len(item) == 2:
                items.append((item[0], item[1]))
            else:
                # Skip invalid entry
                continue

    # Split into control and nested arguments.
    for key, value in items:
        # Treat keys starting with "ctrl_" or a leading underscore as control.
        if key.startswith('ctrl_') or key.startswith('_'):
            control_args[key] = value
        # Treat keys starting with "custom_" as custom ansible variables
        # (kept in nested_args because they are written to the spec file).
        elif key.startswith('custom_'):
            nested_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

