def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Normalise args to a mapping: support dict or list of key/value pairs
    if isinstance(args, dict):
        arg_items = args.items()
    elif isinstance(args, (list, tuple)):
        # if items are tuples like (key, value) or (key, value, ...)
        arg_items = [(k, v) for k, v in args if len((k, v)) == 2]
    else:
        raise TypeError("args must be a dict or a list/tuple of key/value pairs")

    control_args = {}
    nested_args = {}
    # If a custom convention is required, it can be inserted here.
    for k, v in arg_items:
        # Treat keys that start with an underscore as control arguments
        if isinstance(k, str) and k.startswith("_"):
            control_args[k] = v
        else:
            # All other keys are considered nested arguments
            nested_args[k] = v
    return control_args, nested_args

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not extra_vars:
        return vars_dict

    # If extra_vars is a dictionary, update directly
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    else:
        # Expecting an iterable of (key, value) pairs
        for kv in extra_vars:
            if isinstance(kv, (list, tuple)) and len(kv) == 2:
                key, value = kv
                vars_dict[key] = value
            else:
                raise ValueError("Each element in extra_vars must be a (key, value) pair.")
    return vars_dict

