@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not extra_vars:
        return vars_dict

    for ev in extra_vars:
        # Strings expecting "key=value"
        if isinstance(ev, str) and '=' in ev:
            key, value = ev.split('=', 1)
            vars_dict[key.strip()] = value.strip()
        # Dictionary items
        elif isinstance(ev, dict):
            vars_dict.update(ev)
        # Tuple or list items of length 2
        elif isinstance(ev, (tuple, list)) and len(ev) == 2:
            key, value = ev
            vars_dict[key] = value
        else:
            # Unsupported format: ignore or raise?
            # We'll ignore it silently for safety.
            continue

    return vars_dict

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not extra_vars:
        return

    # If extra_vars is a mapping, update directly
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
        return

    # Otherwise, iterate through the list or tuple of values
    for item in extra_vars:
        # Handle a two-element tuple/list representing key/value pair
        if isinstance(item, (list, tuple)) and len(item) == 2:
            key, value = item
            vars_dict[key] = value
        # Handle a mapping inside the list
        elif isinstance(item, dict):
            vars_dict.update(item)
        # For any other single value, set it as a key with True as value
        else:
            vars_dict[item] = True

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dict")

    if extra_vars:
        if isinstance(extra_vars, dict):
            items = extra_vars.items()
        else:
            try:
                iter(extra_vars)
                items = extra_vars
            except TypeError:
                raise TypeError("extra_vars must be a dict or iterable of key/value pairs")

        for key, value in items:
            vars_dict[key] = value

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import json
    cmd = ["ansible-playbook"]
    if verbose:
        try:
            lvl = int(verbose)
            if lvl > 0:
                cmd.append("-" + "v" * lvl)
        except Exception:
            pass
    if ansible_args:
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    cmd.append(f"--{key}")
            else:
                cmd.append(f"--{key}={value}")
    if extra_vars:
        cmd.append("--extra-vars")
        cmd.append(json.dumps(extra_vars))
    cmd.append(playbook_path)
    try:
        result = subprocess.run(
            cmd,
            cwd=ir_workspace.root_path() if hasattr(ir_workspace, "root_path") else None,
            capture_output=True,
            text=True,
            check=True,
        )
        output = result.stdout
        if ir_plugin and hasattr(ir_plugin, "report"):
            ir_plugin.report(f"Ansible output:\n{output}")
        return output
    except subprocess.CalledProcessError as exc:
        err = exc.stdout + exc.stderr if hasattr(exc, "stdout") else exc.stderr
        if ir_plugin and hasattr(ir_plugin, "report"):
            ir_plugin.report(f"Ansible failed: {err}")
        raise RuntimeError(f"Ansible playbook failed with return code {exc.returncode}\n{err}") from exc

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """

    import subprocess
    import json

    # Base command
    cmd = ['ansible-playbook', playbook_path]

    # Inventory – try common attributes
    inventory = None
    for attr in ('inventory', 'inventory_path', 'get_inventory_path'):
        if hasattr(ir_workspace, attr):
            inventory = getattr(ir_workspace, attr)
            if callable(inventory):
                inventory = inventory()
            break

    if inventory:
        cmd.extend(['-i', inventory])

    # Add ansible-playbook arguments
    if ansible_args:
        for k, v in ansible_args.items():
            if isinstance(v, bool):
                if v:  # only add flag if True
                    cmd.append(k)
            else:
                cmd.extend([k, str(v)])

    # Verbosity
    if verbose is not None:
        try:
            v = int(verbose)
            if v > 0:
                cmd.append('-' + 'v' * v)
        except ValueError:
            # if not an int, try to use directly if starts with '-'
            if isinstance(verbose, str) and verbose.startswith('-'):
                cmd.append(verbose)

    # Extra vars
    if extra_vars:
        try:
            extra_str = json.dumps(extra_vars)
        except Exception:
            # fallback to string representation
            extra_str = str(extra_vars)
        cmd.extend(['-e', extra_str])

    # Log the command if the plugin offers a logger
    if hasattr(ir_plugin, 'log') and callable(ir_plugin.log):
        ir_plugin.log('Running: ' + ' '.join(cmd))

    # Execute
    result = subprocess.run(cmd, check=True, text=True, capture_output=True)

    # Optional: log stdout/stderr
    if hasattr(ir_plugin, 'log') and callable(ir_plugin.log):
        if result.stdout:
            ir_plugin.log('stdout:\n' + result.stdout)
        if result.stderr:
            ir_plugin.log('stderr:\n' + result.stderr)

    return result.stdout

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
       """
        # Attempt to use a predefined mapping of argument types if available
        arg_type_map = getattr(self, "_arg_type_map", {}).get(parser_name, {})
        for key, val in list(values_dict.items()):
            if val is None:
                continue
            # Use explicit type mapping if defined
            if key in arg_type_map:
                target_type = arg_type_map[key]
                try:
                    values_dict[key] = target_type(val)
                except Exception:
                    # Fall back to string if conversion fails
                    values_dict[key] = val
                continue

            # Generic conversion: try bool, int, float in order
            lower = str(val).lower()
            if lower in ("true", "false"):
                values_dict[key] = lower == "true"
            else:
                try:
                    values_dict[key] = int(val)
                except (ValueError, TypeError):
                    try:
                        values_dict[key] = float(val)
                    except (ValueError, TypeError):
                        # Leave as original string
                        values_dict[key] = val
        # No return value needed; values_dict is modified in place.

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        # Retrieve type mapping for this parser, if any.
        type_map = getattr(self, "parser_arg_types", {}).get(parser_name, {})
        # Iterate over the arguments and convert to the expected type.
        for key, value in list(values_dict.items()):
            expected_type = type_map.get(key)
            if expected_type is None:
                continue  # No conversion required for this argument.

            try:
                # Special handling for booleans – interpret common string representations.
                if expected_type is bool:
                    if isinstance(value, str):
                        # Accept a few typical true/false values.
                        value_lower = value.lower()
                        values_dict[key] = value_lower in ("true", "1", "yes", "y")
                    else:
                        values_dict[key] = bool(value)
                else:
                    # Convert using the expected type constructor.
                    values_dict[key] = expected_type(value)
            except Exception:
                # If conversion fails, leave the original value (often a string) untouched.
                pass
        # The dict is modified in place; return it for convenience.
        return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
       """
        # Type conversion mapping for each parser.  Subclasses or callers may
        # supply a mapping in ``self._type_map`` of the form
        # {parser_name: {arg_name: cast_type, ...}}
        type_map = getattr(self, "_type_map", {}).get(parser_name, {})
        for arg, cast in type_map.items():
            if arg not in values_dict:
                continue
            val = values_dict[arg]
            try:
                if cast is bool:
                    # – interpret common CLI boolean representations
                    if isinstance(val, str):
                        vl = val.lower()
                        if vl in ("true", "1", "yes", "on"):
                            values_dict[arg] = True
                        elif vl in ("false", "0", "no", "off"):
                            values_dict[arg] = False
                        else:
                            # fallback – any non‑empty string is True
                            values_dict[arg] = bool(val)
                    else:
                        values_dict[arg] = bool(val)
                else:
                    # Convert string "None" to None value
                    if isinstance(val, str) and val.lower() == "none":
                        values_dict[arg] = None
                    else:
                        values_dict[arg] = cast(val)
            except Exception as exc:
                raise ValueError(
                    f"Failed to cast argument '{arg}' ({val!r}) to {cast.__name__} "
                    f"for parser '{parser_name}'"
                ) from exc

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    if not isinstance(plugin_dir, dict):
        return {}
    result={}
    def _flatten(d, parent_key=''):
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                _flatten(v, new_key)
            else:
                result[new_key]=v
    _flatten(plugin_dir)
    return result

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    try:
        import json
    except ImportError:
        json = None

    # locate a spec file (JSON or YAML)
    spec_path = None
    for filename in ("spec.json", "spec.yaml", "spec.yml"):
        potential = os.path.join(plugin_dir, filename)
        if os.path.isfile(potential):
            spec_path = potential
            break
    if not spec_path:
        raise FileNotFoundError(
            f"No plugin specification file found in {plugin_dir}. "
            f"Expected one of: spec.json, spec.yaml, spec.yml"
        )

    # load the spec
    if spec_path.endswith(".json"):
        if json is None:
            raise ImportError("No JSON module available to load the spec.")
        with open(spec_path, "r", encoding="utf-8") as f:
            data = json.load(f)
    else:
        try:
            import yaml
        except ImportError as exc:
            raise ImportError(
                "YAML loader is required for '%s' spec files but could "
                "not be imported." % spec_path
            ) from exc
        with open(spec_path, "r", encoding="utf-8") as f:
            data = yaml.safe_load(f)

    # flatten nested dictionaries
    def _flatten(node, prefix=""):
        result = {}
        if isinstance(node, dict):
            for key, value in node.items():
                new_prefix = f"{prefix}.{key}" if prefix else key
                result.update(_flatten(value, new_prefix))
        else:
            result[prefix] = node
        return result

    return _flatten(data)

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Locate the spec file. This function will look for the most common
    # filenames in a predictable order and silently ignore missing ones.
    spec_filenames = ("plugin.json", "plugin.yml", "plugin.yaml")
    spec_path = None
    for fname in spec_filenames:
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            spec_path = path
            break
    if not spec_path:
        return {}

    # Load the specification file.  JSON files are parsed with json,
    # everything else (YAML) is parsed with yaml.safe_load.
    with open(spec_path, "r", encoding="utf-8") as fh:
        if spec_path.endswith(".json"):
            spec = json.load(fh)
        else:
            spec = yaml.safe_load(fh)

    # Helper to recursively flatten a nested dictionary.  Keys from
    # nested levels are concatenated with a dot ('.') separator.
    def _flatten(d, prefix=""):
        flat = {}
        for key, value in d.items():
            composite_key = f"{prefix}.{key}" if prefix else key
            if isinstance(value, dict):
                flat.update(_flatten(value, composite_key))
            else:
                flat[composite_key] = value
        return flat

    return _flatten(spec)

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import json
    import yaml
    from pathlib import Path

    p = Path(plugin_dir)
    if not p.is_dir():
        raise ValueError(f"{plugin_dir} is not a directory")

    # Look for a standard plugin spec file
    spec_file = None
    for name in ("plugin.json", "plugin.yaml", "plugin.yml"):
        candidate = p / name
        if candidate.is_file():
            spec_file = candidate
            break

    if spec_file is None:
        # Fallback: try any JSON or YAML file in the directory
        json_files = list(p.glob("*.json"))
        yaml_files = list(p.glob("*.yaml")) + list(p.glob("*.yml"))
        if json_files:
            spec_file = json_files[0]
        elif yaml_files:
            spec_file = yaml_files[0]
        else:
            raise FileNotFoundError("No plugin specification file found")

    # Load the spec file
    if spec_file.suffix.lower() == ".json":
        with spec_file.open("rt", encoding="utf-8") as fp:
            spec = json.load(fp)
    else:
        with spec_file.open("rt", encoding="utf-8") as fp:
            spec = yaml.safe_load(fp) or {}

    # Helper to recursively flatten dictionaries
    flat = {}

    def _flatten(obj, parent_key=""):
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_key = f"{parent_key}.{k}" if parent_key else k
                _flatten(v, new_key)
        else:
            flat[parent_key] = obj

    _flatten(spec)
    return flat

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    # Find a spec file
    candidates = ['plugin.json', 'plugin.yaml', 'plugin.yml', 'spec.json', 'spec.yaml', 'spec.yml']
    spec_file = None
    for name in candidates:
        path = os.path.join(plugin_dir, name)
        if os.path.isfile(path):
            spec_file = path
            break

    if not spec_file:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    # Load spec
    if spec_file.endswith('.json'):
        with open(spec_file, 'r', encoding='utf-8') as f:
            spec = json.load(f)
    elif yaml and spec_file.endswith(('.yaml', '.yml')):
        with open(spec_file, 'r', encoding='utf-8') as f:
            spec = yaml.safe_load(f)
    else:
        raise ValueError(f"Unsupported spec file format: {spec_file}")

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key=''):
        items = {}
        for key, value in d.items():
            new_key = f"{parent_key}.{key}" if parent_key else key
            if isinstance(value, dict):
                items.update(_flatten(value, new_key))
            elif isinstance(value, list):
                # If list contains dictionaries, flatten each with index suffix
                if all(isinstance(i, dict) for i in value):
                    for idx, itm in enumerate(value):
                        items.update(_flatten(itm, f"{new_key}[{idx}]"))
                else:
                    items[new_key] = value
            else:
                items[new_key] = value
        return items

    return _flatten(spec)

