def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise ValueError("Both path and root must be strings")
    if not root:
        raise ValueError("root cannot be empty")
    # Normalize separators to / for comparison
    norm_root = root.rstrip('/') + '/'
    if path == root:
        return ''
    if path.startswith(norm_root):
        stripped = path[len(norm_root):]
        return stripped
    if path.startswith(root):
        stripped = path[len(root):]
        # Remove leading separator if present
        if stripped.startswith('/') or stripped.startswith('\\'):
            stripped = stripped[1:]
        return stripped
    raise ValueError(f"Root '{root}' does not correspond with path '{path}'")

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    norm_path = os.path.normpath(path)
    norm_root = os.path.normpath(root)
    try:
        relative = os.path.relpath(norm_path, norm_root)
    except ValueError as e:
        raise ValueError(f"Cannot strip root '{root}' from path '{path}': {e}")
    if relative == '.':
        # path is identical to root; return empty string to indicate no remaining path
        return ''
    if relative.startswith('..'):
        raise ValueError(f"root '{root}' is not a prefix of path '{path}'")
    return relative

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")

    # Normalise separators to forward slash for comparison
    norm_path = path.replace('\\', '/')
    norm_root = root.replace('\\', '/')

    # Ensure root ends with a slash to avoid partial matches
    if not norm_root.endswith('/'):
        norm_root_slash = norm_root + '/'
    else:
        norm_root_slash = norm_root

    if norm_path == norm_root.rstrip('/'):
        return ''  # path equals root

    if norm_path.startswith(norm_root_slash):
        stripped = norm_path[len(norm_root_slash):]
        return stripped

    raise ValueError(f"Root {root!r} is not a prefix of path {path!r}")
